window.PMN03_BASE=[{"id": "0011i00000cJ6dJAAS", "hcp": "俊毅 吳", "hco": "吳俊毅身心精神科診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-05-12", "lastFeedback": "向吳醫師告知未來由我接手服務此區域，並詢問醫師煩多閃用於治療MDD跟GAD的病人身上反饋如何，醫師表示都很不錯，沒有特定哪個疾病的人才比較有療效。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6dNAAS", "hcp": "威毅 吳", "hco": "一德身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-08-14", "lastFeedback": "因先前已邀請吳威毅醫師參加 8/29–30 DDM 醫學研討會，惟醫師尚未回覆參與意願，故本次再次至診間與醫師確認。吳醫師表示，今日確認行程後會再回覆是否參加。現場再次向醫師提供活動 Agenda，後續將持續追蹤醫師參與意願及報名情形。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6dVAAS", "hcp": "瑜 單", "hco": "尚語身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-20", "lastFeedback": "拜訪單瑜醫師，詢問明年 ATPC 活動相關贊助事宜。單醫師表示，贊助部分可以提供給我們，活動時間可安排於年前或年後，再依活動時間進一步討論適合的主題及內容。活動規模預計約3–4桌。告知單醫師後續會先與主管確認活動時間及相關規劃，再回覆醫師進一步討論主題、場地及活動細節。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6dZAAS", "hcp": "博文 姜", "hco": "姜博文診所", "specialty": "Endo", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市楊梅區", "lastVisit": "2026-06-30", "lastFeedback": "拜訪蕭醫師，蕭醫師為心臟內科醫師，目前至診所服務約半年。首先詢問醫師是否曾使用過達促朗，醫師表示未曾使用過，也未曾聽過此藥物，過去於醫院服務時並未接觸過達促朗。\n接著詢問醫師臨床上是否常遇到下肢水腫、夜間抽筋、下肢腫脹疼痛等病人，尤其是經檢查心、肝、腎功能無明顯異常者。醫師表示通常若病人有水腫，多半仍會有相關原因，也可能與藥物引起的水腫有關。進一步詢問醫師是否會考慮慢性靜脈疾病的可能性，醫師未特別回覆。後續向醫師介紹達促朗可用於慢性靜脈疾病，並說明其針對下肢腫脹、疼痛、沉重感及夜間抽筋等症狀的療效，同時分享相關文獻與作用機轉。醫師進一步詢問達促朗為何能增加靜脈張力，故向醫師說明達促朗可透過抑制 COMT，增加靜脈血管壁對 noradrenaline 的反應，進而提升靜脈張力、減少靜脈擴張與血液滯留。\n醫師接著詢問是否會造成血壓上升。向醫師說明達促朗主要作用於靜脈血管壁，改善靜脈回流與微循環，並非像升壓藥直接作用於動脈血管造成周邊阻力上升，因此臨床上不會以血壓上升作為主要疑慮。\n蕭醫師表示目前完全沒有接觸過此藥物，因此仍希望再進一步釐清其作用機轉，也會自行查找資料了解。隨後告知醫師，若後續對機轉或臨床文獻有任何問題，皆可再提供資料與醫師分享；也會於下次拜訪時帶其他診間醫師使用達促朗於慢性靜脈疾病病人的實際療效案例，作為臨床應用參考。醫師表示沒有問題。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6e1AAC", "hcp": "冠儀 李", "hco": "九禾藥局(陳炯旭診所)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "因陳醫師於本週日生日，今日特別至診間向陳醫師提前送上生日祝福，並與醫師交流近況、維持PR。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6ecAAC", "hcp": "延壽 楊", "hco": "楊延壽診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市龍潭區", "lastVisit": "2026-07-22", "lastFeedback": "拜訪劉醫師探討其處方狀況。劉醫師表示，對於焦慮憂鬱且伴隨睡眠障礙的病人，會優先考慮使用相關藥物，以減少病人同時服用多種藥物的情形。對於無法耐受SSRI副作用的病人，劉醫師認為影響不大，因其處方習慣為以較低初始劑量開始，讓病人逐步適應。\n同時與劉醫師分享煩多閃在維持體重中線方面的相關文獻，劉醫師表示百憂解亦有類似效果，並提到部分減肥門診會不當使用藥物，甚至開立百憂解給病人。進一步分享文獻中關於體重變化的數據，並建議未來若遇到代謝症候群、肥胖或對體重較為在意的病人，可考慮相關用藥選擇。劉醫師表示未來在處方上會持續觀察與評估。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6eGAAS", "hcp": "子堯 林", "hco": "雷亞診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市八德區", "lastVisit": "2026-09-02", "lastFeedback": "本次拜訪林子堯醫師，主要以閒聊近況為主，持續維持良好互動與關係，交流過程中，林醫師主動提到煩多閃專利期相關話題，並表示對公司整體發展仍有信心。後續林醫師也進一步分享周邊診所及醫師資訊，主動介紹可再前往拜訪的潛在對象。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6eHAAS", "hcp": "彥輝 林", "hco": "平衡身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹市東區", "lastVisit": "2026-08-19", "lastFeedback": "拜訪林彥輝醫師，請醫師協助完成 8/29–30 DDM 醫學研討會之贊助合約書。另外與林醫師詢問 ATPC 相關贊助事宜，林醫師表示，若是大型活動通常會安排在桃園地區，主要考量桃園地區的醫師人數較多；惟相關贊助事宜仍需由單瑜醫師確認，因此後續將再與單醫師進一步詢問及確認。最後邀請林醫師加入公司 LINE OA，方便後續接收醫學活動及相關學術資訊。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6ejAAC", "hcp": "淑娟 江", "hco": "江淑娟身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-07-17", "lastFeedback": "拜訪江醫師，詢問目前主要將煩多閃使用於憂鬱症或焦慮症病人。江醫師表示，臨床上主要用於適應障礙、遭遇職場霸凌或工作壓力較大的病人，初診且伴隨失眠症狀的病人也經常會考慮使用。醫師認為，多數病人通常是在睡眠已受到影響、察覺自身狀況出現問題後才會前來就診，因此煩多閃是其初診處方時常使用的藥物之一。進一步詢問煩多閃的劑量使用情形。江醫師表示，較少將劑量增加至每日兩顆，主要是過去曾聽聞其他醫師因相關處方而遇到健保核刪問題。因此，若病人使用一顆後療效仍不理想，通常會考慮更換為療效較強的 SSRI 類藥物，而非直接增加煩多閃劑量。另詢問醫師是否曾遇過使用煩多閃後肝功能指數升高的病人。江醫師表示目前未曾遇過，且認為實際發生比例相當低。接著向江醫師分享煩多閃維持體重中性的相關文獻，以及比較多種抗憂鬱藥物對體重影響的研究圖表。江醫師表示，從該表格所呈現的藥物排序來看，也符合自己的處方邏輯：通常會先從煩多閃開始使用，若療效不足，再依病人的症狀與治療反應，逐步考慮 sertraline、duloxetine 或其他抗憂鬱藥物。最後邀請江醫師參加 8/29-30舉辦的煩多閃大型研討會。江醫師表示有意願參加，待活動議程確認後，再將完整 agenda 與相關資訊提供給醫師。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6eoAAC", "hcp": "文弘 洪", "hco": "新楊梅診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市楊梅區", "lastVisit": "2026-07-15", "lastFeedback": "邀請洪醫師參加 7 /22餐敘。洪醫師進一步詢問當日與會醫師名單，告知相關資訊後，醫師表示與會陣容十分具有份量，並表示能受邀參加是他的榮幸，確認將於 7 月 22 日出席餐敘<因當日洪醫師延後下診，為避免影響後續行程，本次未再進行深入交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6eYAAS", "hcp": "仲豪 楊", "hco": "暖陽身心科診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "", "lastVisit": "", "lastFeedback": "", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6f5AAC", "hcp": "美君 蕭", "hco": "詠美身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-05-11", "lastFeedback": "護理師表示藥品相關事宜皆由行政人員蔡先生處理，但今日未上班，而蕭醫師則不接洽業務，故另再安排時間拜訪蔡先生。", "savedNext": "找時間拜訪行政人員蔡先生", "notes": ""}, {"id": "0011i00000cJ6fKAAS", "hcp": "瑞祥 邱", "hco": "迎旭診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-04", "lastFeedback": "拜訪李醫師，了解煩多閃近期臨床處方情形。李醫師表示，目前使用煩多閃最大的困擾仍是肝功能監測，並詢問目前是否仍建議病人每個月抽血追蹤。向醫師說明，依仿單建議，應於治療前及治療後第 3、6、12、24 週監測肝功能，完成上述追蹤後，後續可再依病人狀況由醫師評估是否持續追蹤。進一步詢問是否曾遇過肝功能指數升高的病人，李醫師表示目前尚未遇過。不過依其臨床經驗，煩多閃主要使用於情緒症狀較輕微的病人；若病人情緒症狀較明顯，醫師認為使用一顆對情緒改善較有限，通常需增加至兩顆才較能看到效果，因此初診病人是否使用煩多閃，仍會依病人的情緒嚴重程度及臨床表現決定，以上亦為醫師個人的臨床使用經驗。另詢問醫師，若遇到無法耐受 SSRI／SNRI 副作用的病人，是否會考慮改用煩多閃。李醫師表示確實曾遇過此類病人，但若採取漸進式調整劑量，大多仍能耐受副作用，因此未必會立即更換為煩多閃，仍會依病人的情緒反應及治療需求選擇最適合的藥物。最後與醫師分享煩多閃維持體重中性的相關文獻，並詢問是否曾遇過因抗憂鬱藥物造成體重增加而困擾的病人。李醫師表示，自己臨床上較少遇到此類情形。看到文獻後，醫師笑稱：「那以後也可以當減肥藥用了。」隨即向醫師說明，煩多閃的特色在於維持體重中性，而非具有減重效果。醫師表示了解，後續將再持續交流煩多閃於不同病人族群的臨床定位及適合的使用情境。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6fMAAS", "hcp": "信麟 郭", "hco": "悅情身心科診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "", "lastVisit": "", "lastFeedback": "", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6fnAAC", "hcp": "炯旭 陳", "hco": "九禾藥局(陳炯旭診所)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "High Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "因陳醫師於本週日生日，今日特別至診間向陳醫師提前送上生日祝福，並與醫師交流近況、維持PR。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6fUAAS", "hcp": "佳惠 陳", "hco": "九禾藥局(陳炯旭診所)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "因陳醫師於本週日生日，今日特別至診間向陳醫師提前送上生日祝福，並與醫師交流近況、維持PR。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6g8AAC", "hcp": "嘉彬 黃", "hco": "尚語身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-08-20", "lastFeedback": "拜訪單瑜醫師，詢問明年 ATPC 活動相關贊助事宜。單醫師表示，贊助部分可以提供給我們，活動時間可安排於年前或年後，再依活動時間進一步討論適合的主題及內容。活動規模預計約3–4桌。告知單醫師後續會先與主管確認活動時間及相關規劃，再回覆醫師進一步討論主題、場地及活動細節。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6gCAAS", "hcp": "立偉 黃", "hco": "九禾藥局(陳炯旭診所)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "因陳醫師於本週日生日，今日特別至診間向陳醫師提前送上生日祝福，並與醫師交流近況、維持PR。", "savedNext": "", "notes": ""}, {"id": "0011i00000llqWsAAI", "hcp": "煦宗 呂", "hco": "台齡身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "本次拜訪呂宗煦醫師，針對醫師先前對煩多閃肝功能安全性的疑慮，分享相關肝功能安全性文獻，與醫師進一步交流。呂醫師表示，雖然了解相關文獻內容，但對於煩多閃可能影響肝功能仍抱有疑慮，因此臨床上仍會主動告知病人相關風險，讓病人在充分了解後自行評估是否接受煩多閃治療。另外，本次亦與藥師交換聯絡資訊，方便後續進行產品及相關學術資訊交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000llqWxAAI", "hcp": "凱理 張", "hco": "福德身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-08-24", "lastFeedback": "因今日診間病人較多，櫃檯表示今日不便拜訪。", "savedNext": "", "notes": ""}, {"id": "0011i00000oYKGgAAO", "hcp": "濬廷 陳", "hco": "聖洸身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-07-14", "lastFeedback": "拜訪陳醫師，與醫師討論煩多閃於臨床上的使用經驗。陳醫師表示，目前主要將煩多閃使用於兩類病人：一為使用 SSRI、SNRI 或 NDRI 後因副作用無法耐受、需轉換治療的病人；二為症狀較輕的憂鬱或焦慮病人。醫師認為煩多閃屬於較溫和的抗憂鬱、抗焦慮藥物，因此較適合作為輕症病人的治療選擇。針對睡眠改善，陳醫師表示，煩多閃的效果通常不會立即顯現，因此仍需依病人的治療期待與臨床反應調整。若病人認為煩多閃對睡眠改善不足，醫師通常不會立即停藥，而是視情況搭配 BZD 類藥物改善睡眠。\n醫師認為煩多閃較可惜之處在於需監測肝功能。雖然發生肝功能異常的比例不高，但病人仍可能因此有所顧慮。基於療效與風險的考量，醫師通常不會將劑量增加至2 顆，最多僅視病人反應增加至 1.5 顆。若病人於初期使用即無明顯療效，則多半會判斷該病人對煩多閃反應有限，並考慮調整治療策略。陳醫師表示，其整體治療理念仍以心理治療為主、藥物治療為輔。初期會先利用藥物協助病人穩定情緒，再逐步引導病人探索造成情緒困擾的根本原因，期望透過心理治療改善病人的整體狀況。醫師認為，唯有從根本原因著手，才能獲得較長期且穩定的治療成效。另針對其他治療方式，陳醫師表示對 rTMS、自律神經檢測等輔助治療興趣不高，認為其多屬短期改善，未必能解決問題根源；臨床上仍較傾向採用傳統精神科治療模式。醫師亦表示，目前尚未遇到令其特別認可的心理師，因此若病人有心理治療需求，多由自己親自進行晤談與治療。醫師分享，其最有成就感的案例為一位病人經過持續心理治療後，從未使用藥物，整體狀況亦獲得明顯改善。整體而言，陳醫師目前仍有使用煩多閃，但因自身藥物治療比例本就不高，加上認為對於中重度或難治型憂鬱症病人的療效較有限，因此仍會依病人的症狀嚴重度與臨床需求，選擇最適合的治療方式。", "savedNext": "", "notes": ""}, {"id": "0011i00000oYKGiAAO", "hcp": "正龍 黃", "hco": "黃正龍診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市平鎮區", "lastVisit": "2026-07-17", "lastFeedback": "因先前曾協助診所調度煩多閃，故今日前往診所取回相關藥品，並原預計拜訪黃醫師，邀請醫師參加 7/22 餐敘活動。惟當日黃醫師候診病人眾多，短時間內較難安排拜訪，加上後續尚有其他事項需處理，故本次先行離開，未能與醫師進一步交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000oYKGjAAO", "hcp": "正熙 謝", "hco": "正文身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "High Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-27", "lastFeedback": "因上次已與診所辦理達促朗RTM，本次再次拜訪謝正熙醫師，延續活動後續追蹤。詢問謝醫師是否方便於診間張貼達促朗相關海報，以及擺放病人衛教單張，供有痔瘡或慢性靜脈疾病相關症狀的病人參考。謝醫師表示皆沒問題，可於診間提供相關衛教資訊。另外，謝醫師希望能取得上次 RTM 使用的 Slide 作為後續參考，故後續將整理相關資料並傳送給醫師。", "savedNext": "", "notes": ""}, {"id": "0011i00000oYKGoAAO", "hcp": "宏川 林", "hco": "心晴診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-08-03", "lastFeedback": "拜訪唐醫師，了解煩多閃近期臨床使用情形。唐醫師表示，自己認為煩多閃最大的優勢在於改善睡眠，過去雖曾參與多場相關學術演講，但實際使用後認為，對睡眠確實有幫助；然而在憂鬱症及焦慮症的改善上，整體療效相對較為溫和，沒有特別突出的感受。醫師進一步表示，煩多閃並非病人睡眠改善後即可停藥，停藥後仍可能再次出現失眠問題，因此臨床上仍需持續使用。針對此部分，向醫師說明煩多閃主要是藉由作用於 MT1／MT2 褪黑激素受體，協助維持正常晝夜節律，而非直接增加體內褪黑激素濃度。進一步詢問醫師，若遇到無法耐受 SSRI 或 SNRI 副作用的病人，是否會優先考慮使用煩多閃。唐醫師表示，除了煩多閃之外，也會考慮使用 Bupropion，因其副作用相對較少，也是常用的替代選擇。向醫師分享，煩多閃除可治療憂鬱症外，亦可改善睡眠品質，部分病人或許可減少額外使用安眠藥的需求。唐醫師則表示，若病人僅有失眠問題，為了開立煩多閃而給予診斷並不恰當，因此仍會以其他安眠藥物作為主要治療。此外，許多失眠病人病程已相當長，對於藥物是否具有依賴性或成癮性的顧慮相對較低，因此臨床上仍以改善睡眠為主要考量。交流過程中，唐醫師也分享曾聽過另一種作用於褪黑激素系統的助眠藥物，但因未實際使用，無法評論臨床效果；另外提到食慾素受體拮抗劑 Dayvigo，處方經驗認為效果普通，曾遇過一位病人出現血壓不穩的情形，雖查閱仿單未見相關警示，但也再次體會到不同藥物在不同病人身上的反應仍存在個體差異。最後，原欲向唐醫師分享煩多閃維持體重中性的相關文獻，醫師表示較習慣閱讀紙本文獻，長時間閱讀平板容易感到頭暈不適；此外，目前自行取得文獻亦較不方便，因此希望能提供紙本資料。告知醫師下次拜訪時將攜帶相關紙本文獻，供醫師參考及交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000oYKGpAAO", "hcp": "洵 李", "hco": "迎旭診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-08-04", "lastFeedback": "拜訪李醫師，了解煩多閃近期臨床處方情形。李醫師表示，目前使用煩多閃最大的困擾仍是肝功能監測，並詢問目前是否仍建議病人每個月抽血追蹤。向醫師說明，依仿單建議，應於治療前及治療後第 3、6、12、24 週監測肝功能，完成上述追蹤後，後續可再依病人狀況由醫師評估是否持續追蹤。進一步詢問是否曾遇過肝功能指數升高的病人，李醫師表示目前尚未遇過。不過依其臨床經驗，煩多閃主要使用於情緒症狀較輕微的病人；若病人情緒症狀較明顯，醫師認為使用一顆對情緒改善較有限，通常需增加至兩顆才較能看到效果，因此初診病人是否使用煩多閃，仍會依病人的情緒嚴重程度及臨床表現決定，以上亦為醫師個人的臨床使用經驗。另詢問醫師，若遇到無法耐受 SSRI／SNRI 副作用的病人，是否會考慮改用煩多閃。李醫師表示確實曾遇過此類病人，但若採取漸進式調整劑量，大多仍能耐受副作用，因此未必會立即更換為煩多閃，仍會依病人的情緒反應及治療需求選擇最適合的藥物。最後與醫師分享煩多閃維持體重中性的相關文獻，並詢問是否曾遇過因抗憂鬱藥物造成體重增加而困擾的病人。李醫師表示，自己臨床上較少遇到此類情形。看到文獻後，醫師笑稱：「那以後也可以當減肥藥用了。」隨即向醫師說明，煩多閃的特色在於維持體重中性，而非具有減重效果。醫師表示了解，後續將再持續交流煩多閃於不同病人族群的臨床定位及適合的使用情境。", "savedNext": "", "notes": ""}, {"id": "0011i00000W1fLaAAJ", "hcp": "台齡 吳", "hco": "台齡身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "本次拜訪呂宗煦醫師，針對醫師先前對煩多閃肝功能安全性的疑慮，分享相關肝功能安全性文獻，與醫師進一步交流。呂醫師表示，雖然了解相關文獻內容，但對於煩多閃可能影響肝功能仍抱有疑慮，因此臨床上仍會主動告知病人相關風險，讓病人在充分了解後自行評估是否接受煩多閃治療。另外，本次亦與藥師交換聯絡資訊，方便後續進行產品及相關學術資訊交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000W1fLbAAJ", "hcp": "麗卿 陳", "hco": "台齡身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "本次拜訪呂宗煦醫師，針對醫師先前對煩多閃肝功能安全性的疑慮，分享相關肝功能安全性文獻，與醫師進一步交流。呂醫師表示，雖然了解相關文獻內容，但對於煩多閃可能影響肝功能仍抱有疑慮，因此臨床上仍會主動告知病人相關風險，讓病人在充分了解後自行評估是否接受煩多閃治療。另外，本次亦與藥師交換聯絡資訊，方便後續進行產品及相關學術資訊交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000W1fLzAAJ", "hcp": "嘉良 彭", "hco": "嘉良診所", "specialty": "Internal Medicine", "product": "Diamicron MR", "adoption": "Medium Prescriber", "grade": "C", "target": 2, "area": "新竹", "lastVisit": "2024-08-15", "lastFeedback": "報價戴密克隆30大口價格。（要跟太太報,太太訂貨）跟醫師細細介紹達促朗,彭醫師非常有興趣但是對於療效不認為可以像我們data說的七天就改善。待下次追蹤。", "savedNext": "", "notes": ""}, {"id": "0011i00000W1fODAAZ", "hcp": "能清 陳", "hco": "能清安欣診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹市東區", "lastVisit": "2026-08-25", "lastFeedback": "拜訪陳醫師，關心近期診間狀況並維持良好關係，同時了解煩多閃近期病人使用情形。陳醫師表示，目前病人使用煩多閃後整體沒有遇到明顯副作用，過去曾遇到的肝功能相關問題，近期也沒有再遇到。陳醫師本身較不偏好使用 SSRI 類藥物，因此認為煩多閃在臨床上是一個蠻好使用的選擇。進一步詢問若遇到更年期婦女合併失眠、焦慮等症狀，陳醫師表示會考慮使用煩多閃，因為更年期婦女常見的情緒及睡眠症狀與焦慮表現有所重疊。醫師表示，臨床上煩多閃不論焦慮或憂鬱相關症狀皆會考慮使用，且整體耐受性良好、副作用相對少。另外詢問陳醫師是否曾遇過神經痛患者使用煩多閃，陳醫師表示曾聽聞臨床上有此類處方方式，但目前沒有聽過以 BID 方式使用的案例。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws0AAB", "hcp": "勤益 高", "hco": "安心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-08-24", "lastFeedback": "拜訪高勤益醫師，先與醫師維持（PR），並進一步了解目前煩多閃處方情形。高醫師表示，目前診間持續穩定開立煩多閃，整體而言病人使用後副作用相對少，臨床上較常遇到頭暈、頭痛等情形。醫師另分享曾遇過一位病人使用煩多閃後，隔天有疲憊感，因此後續直接協助病人更換藥物。針對此情況，向高醫師分享若未來再遇到類似病人，可視個案情況嘗試將服藥時間提前至晚餐後，觀察是否有助於改善隔日疲憊感；醫師表示了解。後續至藥局拜訪藥師，藥師表示近期剛好有叫藥需求，故協助診所訂購煩多閃 100+18。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws1AAB", "hcp": "為文 林", "hco": "心寧診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-31", "lastFeedback": "原預計前往診所拜訪梁欽綺醫師，惟抵達後發現診所門口張貼今日上午休診公告，故本次未能完成拜訪。後續將重新確認梁醫師門診時間，擇日再安排拜訪。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws2AAB", "hcp": "欽琦 梁", "hco": "心寧診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-31", "lastFeedback": "原預計前往診所拜訪梁欽綺醫師，惟抵達後發現診所門口張貼今日上午休診公告，故本次未能完成拜訪。後續將重新確認梁醫師門診時間，擇日再安排拜訪。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws3AAB", "hcp": "晴玉 林", "hco": "心晴診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-03", "lastFeedback": "拜訪唐醫師，了解煩多閃近期臨床使用情形。唐醫師表示，自己認為煩多閃最大的優勢在於改善睡眠，過去雖曾參與多場相關學術演講，但實際使用後認為，對睡眠確實有幫助；然而在憂鬱症及焦慮症的改善上，整體療效相對較為溫和，沒有特別突出的感受。醫師進一步表示，煩多閃並非病人睡眠改善後即可停藥，停藥後仍可能再次出現失眠問題，因此臨床上仍需持續使用。針對此部分，向醫師說明煩多閃主要是藉由作用於 MT1／MT2 褪黑激素受體，協助維持正常晝夜節律，而非直接增加體內褪黑激素濃度。進一步詢問醫師，若遇到無法耐受 SSRI 或 SNRI 副作用的病人，是否會優先考慮使用煩多閃。唐醫師表示，除了煩多閃之外，也會考慮使用 Bupropion，因其副作用相對較少，也是常用的替代選擇。向醫師分享，煩多閃除可治療憂鬱症外，亦可改善睡眠品質，部分病人或許可減少額外使用安眠藥的需求。唐醫師則表示，若病人僅有失眠問題，為了開立煩多閃而給予診斷並不恰當，因此仍會以其他安眠藥物作為主要治療。此外，許多失眠病人病程已相當長，對於藥物是否具有依賴性或成癮性的顧慮相對較低，因此臨床上仍以改善睡眠為主要考量。交流過程中，唐醫師也分享曾聽過另一種作用於褪黑激素系統的助眠藥物，但因未實際使用，無法評論臨床效果；另外提到食慾素受體拮抗劑 Dayvigo，處方經驗認為效果普通，曾遇過一位病人出現血壓不穩的情形，雖查閱仿單未見相關警示，但也再次體會到不同藥物在不同病人身上的反應仍存在個體差異。最後，原欲向唐醫師分享煩多閃維持體重中性的相關文獻，醫師表示較習慣閱讀紙本文獻，長時間閱讀平板容易感到頭暈不適；此外，目前自行取得文獻亦較不方便，因此希望能提供紙本資料。告知醫師下次拜訪時將攜帶相關紙本文獻，供醫師參考及交流。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws4AAB", "hcp": "當陽 梅", "hco": "當陽之境身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-08-27", "lastFeedback": "因梅當陽醫師從友人處得知公司本週六有舉辦醫學研討會活動，先由藥師協助來電詢問活動及住宿相關資訊，並表示若有住宿安排就會參加，故本次特別前往診所拜訪梅醫師並說明活動內容。梅醫師表示，其實目前仍在考慮是否參加，預計下午確認行程後再給予回覆，故後續將持續追蹤醫師參與意願。交流過程中亦了解煩多閃處方情形。梅醫師表示，目前都有穩定使用煩多閃，自己臨床上尚未遇過肝功能指數升高的病人。不過過去曾有一位由新竹榮總轉診而來的患者，表示使用煩多閃期間肝功能指數曾升高至約 300，當時榮總醫師並未明確向病人說明肝功能異常與藥物之間的因果關係，使病人對此感到失望；該患者後續停藥後，肝功能則恢復正常。由於梅醫師平時較少接受業務拜訪，本次藉由活動邀約機會與醫師建立初步關係，並成功交換聯絡資訊，方便後續提供活動及相關學術資訊，持續維持醫師關係。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9ws5AAB", "hcp": "偉雄 徐", "hco": "楊延壽診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 6, "area": "桃園市龍潭區", "lastVisit": "2026-07-22", "lastFeedback": "拜訪劉醫師探討其處方狀況。劉醫師表示，對於焦慮憂鬱且伴隨睡眠障礙的病人，會優先考慮使用相關藥物，以減少病人同時服用多種藥物的情形。對於無法耐受SSRI副作用的病人，劉醫師認為影響不大，因其處方習慣為以較低初始劑量開始，讓病人逐步適應。\n同時與劉醫師分享煩多閃在維持體重中線方面的相關文獻，劉醫師表示百憂解亦有類似效果，並提到部分減肥門診會不當使用藥物，甚至開立百憂解給病人。進一步分享文獻中關於體重變化的數據，並建議未來若遇到代謝症候群、肥胖或對體重較為在意的病人，可考慮相關用藥選擇。劉醫師表示未來在處方上會持續觀察與評估。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9wt4AAB", "hcp": "正修 林", "hco": "林正修診所/千仟藥局", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "C", "target": 3, "area": "新竹市東區", "lastVisit": "2026-07-16", "lastFeedback": "拜訪林醫師，了解煩多閃目前的臨床處方情形。林醫師首先詢問，煩多閃造成肝功能異常的發生率是否在台灣較低。\n向林醫師分享台灣藥害救濟，比較煩多閃、mirtazapine 及 trazodone 三種藥物的藥物性肝損傷發生情形。研究結果顯示，煩多閃在三種藥物中並未顯著增加肝功能異常的風險。此外，亦分享國外文獻資料，使用 25 mg 時肝功能指數升高的發生率約為 1%，50 mg 約為 2.5%。進一步詢問林醫師是否曾遇過相關個案，醫師表示曾遇過一位病人出現肝功能指數升高，因此即停用煩多閃，後續未再繼續使用。不過醫師仍認為，煩多閃整體屬於較溫和的抗憂鬱藥物。另詢問診間是否常遇到因 SSRI 或 SNRI 副作用而無法耐受的病人。林醫師表示確實有，以腸胃道副作用最為常見，而性功能障礙較少由病人主動提出。進一步詢問若病人因副作用無法耐受，是否會考慮改用煩多閃，醫師表示會，若病人耐受性不佳，會將煩多閃作為替代治療選項。拜訪過程中亦與林醫師分享煩多閃維持體重中性的相關文獻。林醫師表示，臨床上確實有部分病人在使用 SSRI 後出現體重增加的情形，因此對於重視體重控制、肥胖或合併代謝症候群的病人，煩多閃確實可作為適合的治療選擇。最後與林醫師討論煩多閃對失樂感的改善效果。林醫師表示，目前尚未特別觀察到病人在此方面有明顯改善。故進一步分享煩多閃因拮抗 5-HT2C 受體，可增加前額葉多巴胺及正腎上腺素的釋放，理論上有助於改善動機及失樂感，建議醫師後續可於臨床持續觀察相關病人的治療反應，後續亦將持續分享最新文獻與臨床資料供醫師參考。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9wtAAAR", "hcp": "姵宇 姚", "hco": "安立身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "拜訪姚姵宇醫師，確認醫師是否能參加 8/29–30 DDM 醫學研討會活動。姚醫師表示，確認行程後發現該週已有其他安排，因此此次無法參加 DDM 活動。後續將持續維持與醫師之關係，未來有合適的學術活動再進行邀約。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9wtEAAR", "hcp": "大元 馬", "hco": "馬大元診所/全民好藥局", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 3, "area": "新竹市東區", "lastVisit": "2026-08-10", "lastFeedback": "拜訪陳其祥醫師，先進行自我介紹並了解診間主要病人族群。陳醫師雖具老人精神科專業，但表示目前診間老年病人比例並不高，主要還是以失眠相關患者為主。進一步詢問醫師對於失眠病人的用藥習慣，陳醫師表示仍會依病人整體症狀及臨床需求決定單一藥物或合併其他藥物治療。若遇到憂鬱合併失眠的病人，臨床上也會使用煩多閃治療。陳醫師表示，部分病人會自行查詢煩多閃相關資訊後，因看到可能影響肝功能而產生疑慮，不過實際安排病人檢查後，目前並未遇到肝功能指數升高的情形。針對醫師及病人對肝功能監測的疑慮，告知下次拜訪時將攜帶相關肝功能安全性文獻與醫師分享，進一步交流煩多閃的臨床使用經驗。", "savedNext": "", "notes": ""}, {"id": "0011i00000X9wtZAAR", "hcp": "昇岱 劉", "hco": "林正修診所/千仟藥局", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "新竹市東區", "lastVisit": "2026-07-16", "lastFeedback": "拜訪林醫師，了解煩多閃目前的臨床處方情形。林醫師首先詢問，煩多閃造成肝功能異常的發生率是否在台灣較低。\n向林醫師分享台灣藥害救濟，比較煩多閃、mirtazapine 及 trazodone 三種藥物的藥物性肝損傷發生情形。研究結果顯示，煩多閃在三種藥物中並未顯著增加肝功能異常的風險。此外，亦分享國外文獻資料，使用 25 mg 時肝功能指數升高的發生率約為 1%，50 mg 約為 2.5%。進一步詢問林醫師是否曾遇過相關個案，醫師表示曾遇過一位病人出現肝功能指數升高，因此即停用煩多閃，後續未再繼續使用。不過醫師仍認為，煩多閃整體屬於較溫和的抗憂鬱藥物。另詢問診間是否常遇到因 SSRI 或 SNRI 副作用而無法耐受的病人。林醫師表示確實有，以腸胃道副作用最為常見，而性功能障礙較少由病人主動提出。進一步詢問若病人因副作用無法耐受，是否會考慮改用煩多閃，醫師表示會，若病人耐受性不佳，會將煩多閃作為替代治療選項。拜訪過程中亦與林醫師分享煩多閃維持體重中性的相關文獻。林醫師表示，臨床上確實有部分病人在使用 SSRI 後出現體重增加的情形，因此對於重視體重控制、肥胖或合併代謝症候群的病人，煩多閃確實可作為適合的治療選擇。最後與林醫師討論煩多閃對失樂感的改善效果。林醫師表示，目前尚未特別觀察到病人在此方面有明顯改善。故進一步分享煩多閃因拮抗 5-HT2C 受體，可增加前額葉多巴胺及正腎上腺素的釋放，理論上有助於改善動機及失樂感，建議醫師後續可於臨床持續觀察相關病人的治療反應，後續亦將持續分享最新文獻與臨床資料供醫師參考。", "savedNext": "", "notes": ""}, {"id": "0011i00000y2we5AAA", "hcp": "永龍 陳", "hco": "育禾診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園", "lastVisit": "2025-07-01", "lastFeedback": "陳醫師說遇到去年有遇到核刪，好像去年還前年是說沒有MDD會被刪，我跟陳醫師說今年核刪有聽說比較緩和了，請陳醫師放心", "savedNext": "", "notes": ""}, {"id": "0011i000010LRTEAA4", "hcp": "大偉 陳", "hco": "欣悅診所(桃園)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市蘆竹區", "lastVisit": "2026-08-21", "lastFeedback": "原預計拜訪林為文醫師，抵達診所後發現診間未開門，後續至診所官網查閱門診資訊，確認林醫師今日休診，故本次未能完成拜訪。後續擇日拜訪前，將先至診所官網確認當日門診是否如常，以避免再次遇到休診情形。", "savedNext": "", "notes": ""}, {"id": "0011i000010MmPsAAK", "hcp": "志偉 丁", "hco": "北屯好晴天身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Trialist", "grade": "C", "target": 2, "area": "", "lastVisit": "", "lastFeedback": "", "savedNext": "", "notes": ""}, {"id": "0011i000014vCSWAA2", "hcp": "嘉良 唐", "hco": "心晴診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-08-03", "lastFeedback": "拜訪唐醫師，了解煩多閃近期臨床使用情形。唐醫師表示，自己認為煩多閃最大的優勢在於改善睡眠，過去雖曾參與多場相關學術演講，但實際使用後認為，對睡眠確實有幫助；然而在憂鬱症及焦慮症的改善上，整體療效相對較為溫和，沒有特別突出的感受。醫師進一步表示，煩多閃並非病人睡眠改善後即可停藥，停藥後仍可能再次出現失眠問題，因此臨床上仍需持續使用。針對此部分，向醫師說明煩多閃主要是藉由作用於 MT1／MT2 褪黑激素受體，協助維持正常晝夜節律，而非直接增加體內褪黑激素濃度。進一步詢問醫師，若遇到無法耐受 SSRI 或 SNRI 副作用的病人，是否會優先考慮使用煩多閃。唐醫師表示，除了煩多閃之外，也會考慮使用 Bupropion，因其副作用相對較少，也是常用的替代選擇。向醫師分享，煩多閃除可治療憂鬱症外，亦可改善睡眠品質，部分病人或許可減少額外使用安眠藥的需求。唐醫師則表示，若病人僅有失眠問題，為了開立煩多閃而給予診斷並不恰當，因此仍會以其他安眠藥物作為主要治療。此外，許多失眠病人病程已相當長，對於藥物是否具有依賴性或成癮性的顧慮相對較低，因此臨床上仍以改善睡眠為主要考量。交流過程中，唐醫師也分享曾聽過另一種作用於褪黑激素系統的助眠藥物，但因未實際使用，無法評論臨床效果；另外提到食慾素受體拮抗劑 Dayvigo，處方經驗認為效果普通，曾遇過一位病人出現血壓不穩的情形，雖查閱仿單未見相關警示，但也再次體會到不同藥物在不同病人身上的反應仍存在個體差異。最後，原欲向唐醫師分享煩多閃維持體重中性的相關文獻，醫師表示較習慣閱讀紙本文獻，長時間閱讀平板容易感到頭暈不適；此外，目前自行取得文獻亦較不方便，因此希望能提供紙本資料。告知醫師下次拜訪時將攜帶相關紙本文獻，供醫師參考及交流。", "savedNext": "", "notes": ""}, {"id": "0011i000015vyszAAA", "hcp": "志弘 許", "hco": "許志弘診所", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "Conscious Non Prescriber", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-06-18", "lastFeedback": "詢問藥師目前痔瘡用藥狀況，藥師表示目前多使用黃氏 Diosmin，效果尚佳且價格較低，病人接受度較高，後續將再拜訪醫師進一步了解用藥考量。另邀約許醫師參加 7/11–7/12 SPA 活動，許醫師表示可先提供 agenda 參考，後續再評估是否參與，並表示可透過活動進一步了解達促朗相關臨床實證。", "savedNext": "", "notes": ""}, {"id": "0011i000015vyxBAAQ", "hcp": "應德 李", "hco": "李應德診所", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園", "lastVisit": "2024-01-22", "lastFeedback": "拿自製的衛教單張給醫師，詢問近期處方的狀況.醫師表示他現在會推在術後，另外也告訴我近期有許多學名要來找他，但他認為那些學名藥療效不會像我們這麼好.我與醫師分享使用我們的產品也比較不會因為價格在外面被打到而影響醫病關係", "savedNext": "", "notes": ""}, {"id": "0011i00001Aw5oCAAR", "hcp": "信志 劉", "hco": "劉信志診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "High Prescriber", "grade": "C", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-08-10", "lastFeedback": "拜訪劉信志醫師，攜帶達促朗相關衛教單張至診所，提供診所作為病人衛教使用。另詢問藥師是否方便張貼達促朗相關海報，藥師表示目前診所已有較多海報，張貼空間有限，可能暫無適合位置。本次亦與劉醫師進行近況交流，維持PR。", "savedNext": "", "notes": ""}, {"id": "0011i00001Aw5oqAAB", "hcp": "士潭 莊", "hco": "新誠診所", "specialty": "General Surgery", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-07-30", "lastFeedback": "拜訪莊士潭醫師，與醫師分享達促朗應用於精索靜脈曲張的相關文獻。莊醫師亦分享診間使用達促朗治療痔瘡病人的臨床照片，病人在治療後痔瘡體積明顯縮小，臨床改善相當顯著。莊醫師表示，目前診所仍以包皮手術病人為主，因此達促朗於痔瘡及精索靜脈曲張的使用機會相對有限。後續向醫師分享其他診所醫師使用達促朗於精索靜脈曲張病人的臨床經驗，並特別說明該處方方式屬於其他醫師的臨床經驗分享，並非官方建議的適應症或使用方式。莊醫師表示了解，並認為若未來遇到精索靜脈曲張病人，將會評估病人的病況及自費接受度，若病人願意接受自費治療，會考慮嘗試處方達促朗。", "savedNext": "", "notes": ""}, {"id": "0011i00001AxkyBAAR", "hcp": "立光 游", "hco": "天一胃腸肝膽科診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市中壢區", "lastVisit": "2026-08-20", "lastFeedback": "因上次拜訪時游立光醫師表示，診間病人數較多，較無多餘時間進行產品推廣，建議可於藥局張貼達促朗相關海報，並提供衛教小卡，讓有需求的病人可持小卡至藥局，由藥師協助進行用藥衛教。故本次至藥局協助張貼痔瘡及慢性靜脈疾病相關海報，並提供達促朗衛教小卡予游醫師，方便後續提供病人使用。", "savedNext": "", "notes": ""}, {"id": "0011i00001AxXkfAAF", "hcp": "祥斌 謝", "hco": "謝醫師神經內科診所", "specialty": "Internal Medicine", "product": "Natrilix SR", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園", "lastVisit": "2021-09-23", "lastFeedback": "介紹coveram給院長，院長聽完是說會再考慮看看，不過他本人倒是對複方沒什麼興趣", "savedNext": "下次可能可以提單方的ACE，並說COVERAM是在指引裡的第一線的複方藥物", "notes": ""}, {"id": "0011i00001Hdl4cAAB", "hcp": "孟釗 蔡", "hco": "崇光身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-14", "lastFeedback": "拜訪郭人碩醫師，邀請醫師參加 8/29–30 DDM 醫學研討會活動。郭醫師表示，該週已與高中同學安排聚會，行程已有安排，因此此次無法參加 DDM 活動。後續將於未來有合適的學術活動時再進行邀約。", "savedNext": "", "notes": ""}, {"id": "0011i00001Hdl4hAAB", "hcp": "順志 胡", "hco": "胡順志診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-07-06", "lastFeedback": "拜訪胡醫師，詢問近期痔瘡症狀病人之狀況。胡醫師表示，目前僅遇到一位因痔瘡嚴重疼痛不適而處方達促朗一盒之病人，推測症狀已有明顯改善，因此後續未再回診。\n進一步與胡醫師分享達促朗使用後之臨床案例，醫師表示達促朗確實療效佳，並提到其他廠商產品劑量較低，使用後效果較不明顯，因此對於相關產品接受度較低。不過，針對症狀較輕微之病人，醫師仍會優先建議使用健保藥物。\n後續與醫師討論，可於臨床上提供病人不同治療選擇，若病人希望較快速改善症狀，達促朗可作為治療選項之一。胡醫師表示認同，未來遇到合適病人會再增加嘗試使用，但目前診間仍以腹部相關症狀病人為主。", "savedNext": "", "notes": ""}, {"id": "0011i00001He12vAAB", "hcp": "盈森 張", "hco": "樂康診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-06-24", "lastFeedback": "預拜訪張醫師，查詢上一次購買達促朗時間為 2023 年。進入診所時診間已無候診病患，故詢問櫃檯是否方便拜訪張醫師。櫃檯協助詢問後，張醫師回覆目前仍在忙碌，暫不方便拜訪。後續將擇日再安排時間拜訪，進一步了解目前痔瘡相關病人之處方習慣，並重新分享達促朗於痔瘡治療之臨床應用。", "savedNext": "", "notes": ""}, {"id": "0011i00001N9G0LAAV", "hcp": "明吉 江", "hco": "愛麗康診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-08-24", "lastFeedback": "因上次拜訪時江明吉醫師曾請我提供達促朗英文版衛教小卡，故本次特別將整理完成的英文衛教小卡帶至診間提供給醫師。江醫師表示，目前衛教小卡上的文字較小，閱讀上較不方便，建議下次印製時可改以雙面方式呈現，讓版面及文字能夠放大，閱讀上會更加清楚。後續將依醫師建議調整衛教小卡版面，並於下次提供新版資料。", "savedNext": "", "notes": ""}, {"id": "0011i00001NndC8AAJ", "hcp": "瑞家 林", "hco": "林瑞家診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-08-03", "lastFeedback": "拜訪林醫師，了解達促朗目前的臨床使用情形。林醫師表示，診間無須特別安排產品介紹，若遇到痔瘡或慢性靜脈疾病的病人，仍會主動建議病人至隔壁合作藥局購買達促朗使用。醫師進一步表示，由於診所採釋出處方模式，因此未直接管理藥品進貨事宜，但臨床上若病人有相關適應症，仍會優先建議使用達促朗作為治療選項。", "savedNext": "", "notes": ""}, {"id": "00158000019UBmgAAG", "hcp": "佳益 鄭", "hco": "周伯翰身心醫學診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "新竹縣竹北市", "lastVisit": "2026-08-25", "lastFeedback": "拜訪鄭醫師，了解目前煩多閃之處方情形。鄭醫師表示，目前處方煩多閃時主要使用 F41.1 診斷碼。向醫師補充說明，煩多閃另有 F32.9 相關適應症診斷碼；鄭醫師表示了解，並提到 F32.9 為未明示的憂鬱症，因此目前仍習慣以 F4.1 為主要處方診斷。交流過程中，鄭醫師詢問未來仿單是否有機會擴增兒童族群適應症。醫師表示，兒童可使用的抗憂鬱藥物選擇相對有限，而依其臨床感受，認為煩多閃可能適合部分兒童患者，但因目前仿單未涵蓋兒童使用，因此臨床上也不敢開立，擔心產生相關醫療風險。針對此部分，向鄭醫師說明目前尚未得知仿單近期有擴增兒童適應症的規劃；另外從現有研究來看，兒童族群的研究樣本數仍不足，若未來要進一步支持兒童適應症，可能仍需要更多大型臨床研究資料。另外，鄭醫師提到曾聽周醫師分享，煩多閃的適應症主要為焦慮症及憂鬱症，因此不能單純因病人有失眠症狀就開立煩多閃。對此向醫師確認，煩多閃應使用於符合核准適應症的焦慮症或憂鬱症患者，若同時伴隨睡眠問題，則可將睡眠症狀改善作為治療上的額外考量，而非單純以失眠作為開立依據。進一步詢問鄭醫師對煩多閃改善睡眠的臨床回饋，醫師表示整體效果尚可，對部分病人確實有幫助；加上臨床上感受到副作用相對少，因此目前使用上相對順手，整體而言是一個不錯的藥物選擇。", "savedNext": "", "notes": ""}, {"id": "00158000019UBnxAAG", "hcp": "正元 余", "hco": "能清安欣診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "新竹市東區", "lastVisit": "2026-08-25", "lastFeedback": "拜訪陳醫師，關心近期診間狀況並維持良好關係，同時了解煩多閃近期病人使用情形。陳醫師表示，目前病人使用煩多閃後整體沒有遇到明顯副作用，過去曾遇到的肝功能相關問題，近期也沒有再遇到。陳醫師本身較不偏好使用 SSRI 類藥物，因此認為煩多閃在臨床上是一個蠻好使用的選擇。進一步詢問若遇到更年期婦女合併失眠、焦慮等症狀，陳醫師表示會考慮使用煩多閃，因為更年期婦女常見的情緒及睡眠症狀與焦慮表現有所重疊。醫師表示，臨床上煩多閃不論焦慮或憂鬱相關症狀皆會考慮使用，且整體耐受性良好、副作用相對少。另外詢問陳醫師是否曾遇過神經痛患者使用煩多閃，陳醫師表示曾聽聞臨床上有此類處方方式，但目前沒有聽過以 BID 方式使用的案例。", "savedNext": "", "notes": ""}, {"id": "0017U0000032i1YQAQ", "hcp": "德和 王", "hco": "王德和診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市平鎮區", "lastVisit": "2026-08-28", "lastFeedback": "本次攜帶達促朗衛教小卡至診所提供使用，並向護理師了解近期達促朗的處方及使用情形。護理師表示，王醫師偶爾會將達促朗處方於痔瘡患者，但近期較常使用於慢性靜脈疾病相關患者。另外得知診間陳醫師亦有處方達促朗，故後續將擇日安排拜訪陳醫師，進一步了解其主要處方病人族群、使用方式及臨床回饋，持續追蹤診間達促朗使用情形。", "savedNext": "", "notes": ""}, {"id": "0017U0000032i2RQAQ", "hcp": "宏裕 詹", "hco": "舒欣身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市平鎮區", "lastVisit": "2026-08-28", "lastFeedback": "因徐醫師預計參加 8/29–8/30 DDM 醫學研討會，本次請醫師協助簽署活動相關同意書。徐醫師表示此次不需要住宿，僅會參加其中一天的會議，故無需簽署同意書。接著詢問徐醫師近期煩多閃處方情形。徐醫師表示目前使用狀況良好，尤其男性病人若較在意性功能相關副作用時，會較優先考慮煩多閃。針對憂鬱症患者，徐醫師分享其臨床處方觀點：若為症狀較嚴重的憂鬱患者，起始治療時較不會優先選擇煩多閃，主要考量其認為此類患者初期仍需要較明顯的 SERT 相關作用，以改善憂鬱症狀。進一步詢問煩多閃劑量與療效的臨床經驗，徐醫師表示，焦慮症患者使用一顆時即可能有不錯的效果；但對憂鬱症患者而言，依其臨床經驗，有時可能需要使用至兩顆才較能觀察到效果。", "savedNext": "", "notes": ""}, {"id": "0017U0000032i2WQAQ", "hcp": "風雄 馮", "hco": "尚群診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-08-04", "lastFeedback": "因上次拜訪時，診所門口公告休診至 8/3，故本次再次前往，原預計向醫師介紹達促朗相關資訊及臨床應用。惟抵達診所後，診所仍未開門，故本次未能完成拜訪。後續將持續追蹤診所開診情形，並擇日再安排拜訪，與醫師進行產品及學術資訊交流。", "savedNext": "", "notes": ""}, {"id": "0017U000005gVd0QAE", "hcp": "振洋 汪", "hco": "振心身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "High Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-26", "lastFeedback": "維持PR，並請汪醫師協助完成8/29-30 DDM之贊助合約書。", "savedNext": "", "notes": ""}, {"id": "0017U000005h04IQAQ", "hcp": "明厚 廖", "hco": "廖明厚小兒科", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "新竹", "lastVisit": "2023-07-05", "lastFeedback": "廖醫師拜訪時間通常是W1,W2早上,建議下次此時間拜訪.與櫃檯了解廖醫師通常處方DAF是哪些族群,因為是兒科,小姐表示老人或是有靜脈曲張的人,廖醫師會請他們自費,下次想詢問廖醫師如何推廣。", "savedNext": "", "notes": ""}, {"id": "0017U000005LWz1QAG", "hcp": "煥昇 陳", "hco": "王德和診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市平鎮區", "lastVisit": "2026-08-28", "lastFeedback": "本次攜帶達促朗衛教小卡至診所提供使用，並向護理師了解近期達促朗的處方及使用情形。護理師表示，王醫師偶爾會將達促朗處方於痔瘡患者，但近期較常使用於慢性靜脈疾病相關患者。另外得知診間陳醫師亦有處方達促朗，故後續將擇日安排拜訪陳醫師，進一步了解其主要處方病人族群、使用方式及臨床回饋，持續追蹤診間達促朗使用情形。", "savedNext": "", "notes": ""}, {"id": "0017U00000OvMWqQAN", "hcp": "學斌 姜", "hco": "聊癒之森", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 3, "area": "新竹", "lastVisit": "2022-07-06", "lastFeedback": "院長新開幕診所下周二即將正式開幕，目前院長已有先下定VDX，院長主要是以兒青為主的診所", "savedNext": "", "notes": ""}, {"id": "0017U00000OwJJQQA3", "hcp": "銀保 莊", "hco": "莊耳鼻喉科", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市蘆竹區", "lastVisit": "2026-06-24", "lastFeedback": "拜訪藥局藥師，了解達促朗叫藥狀況。藥師表示，叫藥通常皆由莊醫師自行處理。故隨後至診所拜訪莊醫師，進一步確認使用情形。莊醫師表示目前並未再使用達促朗，推測應為藥師端叫貨。後續再次返回藥局與藥師確認，藥師表示該筆叫貨應主要為立登藥局之主要負責藥師處理，推測可能為慢性處方箋病人使用。後續將再擇日進一步確認實際使用來源及病人類型。", "savedNext": "", "notes": ""}, {"id": "0017U00000PyuIeQAJ", "hcp": "敦仁 蕭", "hco": "敦仁診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-07-14", "lastFeedback": "觀察診間內僅有少數病人，詢問櫃檯是否可拜訪蕭醫師，櫃檯表示因蕭醫師行程較滿，今日暫不適合，會協助將名片轉交給蕭醫師。", "savedNext": "", "notes": ""}, {"id": "0017U00000Pz41LQAR", "hcp": "彥粹 黃", "hco": "德美診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-07-29", "lastFeedback": "本次原預計拜訪黃醫師，惟櫃檯人員表示目前診所不開放醫師接待業務，故改與藥師交流，藥師表示，達促朗目前主要使用於年長者下肢水腫、麻木、疼痛等慢性靜脈疾病相關症狀。由於夏季就診老人家較少，目前診所尚有約三盒庫存。進一步詢問痔瘡病人的使用情形，藥師表示診間亦有痔瘡患者，但數量相對不多。隨後向藥師介紹達促朗於急性痔瘡治療的相關資訊及臨床應用，並詢問是否需要提供病人衛教單張。藥師表示可以，建議下次補貨時一併提供，以利病人衛教及臨床使用。", "savedNext": "", "notes": ""}, {"id": "0017U00000ROkJkQAL", "hcp": "信榮 趙", "hco": "豐年診所", "specialty": "General Surgery", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-05-29", "lastFeedback": "邀請趙醫師參加7/11-12 學術研討會，趙醫師表示謝謝邀請，他因當天有事不克前往。", "savedNext": "", "notes": ""}, {"id": "0017U00000Sn4aVQAR", "hcp": "助成 嚴", "hco": "敦仁診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-07-14", "lastFeedback": "觀察診間內僅有少數病人，詢問櫃檯是否可拜訪蕭醫師，櫃檯表示因蕭醫師行程較滿，今日暫不適合，會協助將名片轉交給蕭醫師。", "savedNext": "", "notes": ""}, {"id": "001Tn000000gfZqIAI", "hcp": "凱仲 楊", "hco": "蘆竹現代診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市蘆竹區", "lastVisit": "2026-08-21", "lastFeedback": "拜訪楊凱仲醫師，請醫師協助完成 8/29–30 SPA 醫學研討會之贊助合約書。完成活動相關文件後，與楊醫師交流近期診所及工作近況。楊醫師分享，目前中壢也預計開設現代診所，後續待診所正式開幕後，將再前往拜訪並進一步了解新診所的病人族群及用藥需求。", "savedNext": "", "notes": ""}, {"id": "001Tn0000013bvSIAQ", "hcp": "翊菁 何", "hco": "何翊菁診所", "specialty": "Family Medicine", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-07-21", "lastFeedback": "本次先至藥局拜訪藥師，了解煩多閃近期的使用情形。藥師表示，近期煩多閃的用量穩定且使用量不少，目前庫存即將用罄，診所已訂購新一批藥品。藥師分享，何醫師對於初次就診且合併睡眠障礙的病人，通常會考慮開立煩多閃；有時也會搭配其他BZD藥物使用。目前何醫師持續穩定處方，臨床上想到合適的病人時便會使用。相較之下，楊醫師目前較少開立煩多閃，藥師不確定是否因楊醫師對產品資訊較不熟悉，故待至中路翊菁拜訪楊醫師。藥師表示何醫師較不喜歡業務於下午時段拜訪，因此本次未進一步打擾何醫師。", "savedNext": "", "notes": ""}, {"id": "001Tn000001dyVIIAY", "hcp": "添貴 林", "hco": "林添貴診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市八德區", "lastVisit": "2026-09-02", "lastFeedback": "本次拜訪林添貴醫師，先了解近期達促朗處方情形。林醫師表示，近期相關病人較少，因此達促朗處方量也相對不多。另外與林醫師交流近期聽聞有神經內科醫師將煩多閃使用於神經痛患者的臨床經驗，並詢問醫師看法。林醫師表示，神經痛治療中確實會使用部分抗憂鬱藥物，並分享其一位在嘉義執業的神經內科同學相當常使用煩多閃，過去曾遇過少數核刪情形，因此自己對此類處方仍會有所顧慮；若改為自費，部分病人又可能因價格因素降低接受度。\n過程中再次向林醫師提醒煩多閃目前核准之適應症，並針對神經痛相關使用補充可能涉及正腎上腺素調控及疼痛傳導的研究方向，但也說明目前仍需以相關文獻資料進一步確認。林醫師隨後以手機查詢煩多閃資訊，並再次確認其抗憂鬱相關適應症。後續將整理煩多閃與神經痛、NE 調控及疼痛傳導相關文獻，再於下次拜訪時與林醫師進一步分享。", "savedNext": "", "notes": ""}, {"id": "001Tn000001e1mdIAA", "hcp": "柏格 許", "hco": "上杉診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "拜訪楊士豪醫師，了解診間痔瘡病人及達促朗目前的處方情形。楊醫師表示，近期診間痔瘡病人蠻多的，亦有執行冷凍及結紮等相關處置。目前達促朗主要會處方於具有明顯症狀的痔瘡病人；若為第四期痔瘡，通常會直接轉介至醫學中心進一步處理。至於接受冷凍或結紮手術的病人，因醫師觀察術後恢復狀況普遍良好，目前較少搭配達促朗使用。針對術後治療情境，向楊醫師分享達促朗亦有相關文獻探討於門診術後使用，可協助減緩術後腫脹及疼痛。楊醫師表示了解，告知醫師下次拜訪時將攜帶相關文獻供其參考，後續再進一步討論達促朗於術後照護的應用。", "savedNext": "", "notes": ""}, {"id": "001Tn000001eDM9IAM", "hcp": "先營 朱", "hco": "朱先營診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Undecided / Unaware", "grade": "C", "target": 2, "area": "新竹縣湖口區", "lastVisit": "2026-07-29", "lastFeedback": "拜訪朱先營醫師，了解達促朗過去的使用情形。朱醫師表示，達促朗目前主要使用於痔瘡病人，臨床療效因人而異，目前診所內尚有一盒庫存尚未使用完。進一步向醫師介紹達促朗於慢性靜脈疾病病人的臨床應用。朱醫師表示，此類病人在診間相對較少，因此目前使用機會有限。過程中，朱醫師進一步詢問公司其他產品，看到煩多閃後表示曾參加過相關課程，知道其為作用於褪黑激素受體的抗憂鬱藥物。隨後詢問醫師診間是否有失眠相關病人，並向醫師補充介紹煩多閃的適應症及臨床定位。朱醫師表示了解，未來若有合適病人會評估使用。最後，朱醫師表示今日可再次訂購達促朗，持續提供臨床病人使用。", "savedNext": "", "notes": ""}, {"id": "001Tn000002aLrDIAU", "hcp": "威佑 陳", "hco": "優仕奇診所", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "Medium Prescriber", "grade": "B", "target": 6, "area": "新竹縣竹北市", "lastVisit": "2026-07-24", "lastFeedback": "本次原預計拜訪陳威祐醫師，惟櫃檯人員表示，拜訪陳醫師須事先以電話預約，因此本次未能完成拜訪，後續將先行預約後再安排拜訪。另張奇男醫師當日有安排手術，故也於診間內，請張醫師協助完成 8/29–8/30 SPA-MIND 活動之贊助合約書簽署。", "savedNext": "", "notes": ""}, {"id": "001Tn000002aN0AIAU", "hcp": "奇男 張", "hco": "優仕奇診所", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹縣竹北市", "lastVisit": "2026-07-24", "lastFeedback": "本次原預計拜訪陳威祐醫師，惟櫃檯人員表示，拜訪陳醫師須事先以電話預約，因此本次未能完成拜訪，後續將先行預約後再安排拜訪。另張奇男醫師當日有安排手術，故也於診間內，請張醫師協助完成 8/29–8/30 SPA-MIND 活動之贊助合約書簽署。", "savedNext": "", "notes": ""}, {"id": "001Tn000003vDlBIAU", "hcp": "仕政 藍", "hco": "宏日診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Undecided / Unaware", "grade": "B", "target": 3, "area": "桃園市蘆竹區", "lastVisit": "2026-07-23", "lastFeedback": "本次拜訪藍醫師，了解近期達促朗的使用情形。藍醫師表示，目前每日持續服用達促朗，服用期間下肢腫脹確實較為改善；若停藥，相關症狀便容易再次出現。因部分使用者曾反映服用後感受不明顯，進一步詢問藍醫師是否曾收到類似回饋。藍醫師表示，達促朗本來就需要持續、長期服用，才能較穩定地感受到效果。針對慢性靜脈疾病或痔瘡病人，藍醫師表示仍會視病人需求主動推薦達促朗。惟因產品屬自費且價格較高，實際推廣並不容易；但若遇到症狀明確且有治療需求的病人，仍會建議使用。痔瘡症狀改善後，也可評估持續服用作為日常保養。", "savedNext": "", "notes": ""}, {"id": "001Tn000004jDq3IAE", "hcp": "宗寬 黃", "hco": "昇元診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-07-22", "lastFeedback": "本次拜訪黃醫師，了解達促朗近期的使用狀況。黃醫師表示，目前達促朗主要由自己與太太服用，因產品價格較高，較不容易向病人推廣。黃醫師說明，現階段主要將達促朗作為日常保養使用，因此服用後並未感受到特別明顯的變化，但仍維持每日服用。向黃醫師說明，若診所進貨數量較多，也可評估推薦予有需求的病人使用。惟黃醫師認為價格仍偏高，且以目前自身保養使用的經驗來看，改善感受並不明顯，因此暫時沒有向病人推廣的必要。進一步向醫師說明，若應用於痔瘡急性期，或下肢靜脈疾病且症狀較明顯的病人，病人對疼痛、腫脹或不適的改善感受可能會較為明顯。黃醫師表示了解，但現階段仍以自用為主，待目前存量服用完畢後會再行訂購。", "savedNext": "", "notes": ""}, {"id": "001Tn000004jK57IAE", "hcp": "俊敏 黃", "hco": "敏昌診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "拜訪黃醫師，與醫師交流達促朗及煩多閃之臨床使用情形。首先詢問達促朗相關使用狀況，黃醫師表示對達促朗已有一定了解，並認為慢性靜脈疾病的內科治療約能改善部分病人的症狀，臨床上仍需搭配彈性襪及生活習慣調整，以達到較完整的治療效果。接著探討煩多閃處方情形，黃醫師表示，對於煩多閃在台灣的使用量相當有印象，也認為公司的行銷策略相當成功。醫師提到，過去對煩多閃的認知主要為憂鬱症治療，對於目前也有醫師將其應用於焦慮症患者感到好奇。黃醫師分享其臨床經驗，認為煩多閃單獨用於重鬱症患者時療效較不明顯，但若與 SSRI 合併使用，臨床效果則較佳；惟若涉及健保給付規範，診所端在處方上仍會有所限制。進一步了解診間主要病人族群，黃醫師表示以中老年患者居多，年輕族群相對較少。針對中年患者可能出現因過度思慮、焦慮合併睡眠問題的情況，與醫師分享其他臨床醫師使用煩多閃於此類病人的回饋，黃醫師表示了解。另外，黃醫師表示自己對煩多閃改善睡眠的效果評價尚可，但臨床上仍會視病人情況搭配其他藥物。向醫師說明煩多閃作用於褪黑激素受體，若能搭配規律作息，有助於調整睡眠。黃醫師表示對此已有了解，目前診間煩多閃處方量其實也不少。最後建議醫師未來若遇到合併睡眠問題及焦慮症狀的中年患者，可再嘗試評估煩多閃的使用，黃醫師表示認同，後續會再增加相關處方嘗試。", "savedNext": "", "notes": ""}, {"id": "001Tn000005qyelIAA", "hcp": "彥鋒 林", "hco": "親禾身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "新竹市東區", "lastVisit": "2026-08-06", "lastFeedback": "拜訪謝采燁醫師，與醫師建立初步關係，並邀請醫師參加 8/29–30 醫學研討會活動。謝醫師表示，需再確認當日行程安排後才能決定是否參加。交流過程中與醫師交換聯絡方式，並告知後續將傳送活動 Agenda 及相關資訊，供醫師參考。後續將持續追蹤醫師參與意願。", "savedNext": "", "notes": ""}, {"id": "001Tn000005vg66IAA", "hcp": "瀛岳 杜", "hco": "和美家醫診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市中壢區", "lastVisit": "2026-08-24", "lastFeedback": "拜訪杜瀛岳醫師，了解近期達促朗處方情形，杜醫師表示，診間目前亦有使用艾歐復龍，但近期較多病人會主動詢問達促朗，且醫師個人臨床上也較常使用達促朗。診間病人類型方面，慢性靜脈疾病及痔瘡患者約各占一半，兩類患者皆有一定的處方需求。交流過程中，杜醫師提及公司過去曾有一項骨質疏鬆相關藥物，認為該藥物臨床效果很好，是非常不錯的產品，但後續停產，對此感到可惜。向醫師說明，印象中該產品後續因MI相關安全性疑慮而停止供應；杜醫師則表示，他認為相關研究結果未必代表絕對的因果關係，也希望未來公司有機會重新生產該產品。最後詢問醫師是否方便於診間張貼達促朗相關海報，杜醫師表示可以，請將海報交由櫃檯人員協助張貼。", "savedNext": "", "notes": ""}, {"id": "001Tn0000074aGRIAY", "hcp": "唐宇 林", "hco": "龍和內兒科診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "", "lastVisit": "", "lastFeedback": "", "savedNext": "", "notes": ""}, {"id": "001Tn0000074uScIAI", "hcp": "美貞 鄧", "hco": "聖德診所_桃園市桃園區", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "C", "target": 2, "area": "桃園", "lastVisit": "2024-07-31", "lastFeedback": "表示院長後來想起有我們達促朗,處方在靜脈曲張居多。有一位固定會購買患者。", "savedNext": "", "notes": ""}, {"id": "001Tn00000B93MwIAJ", "hcp": "彥霖 陳", "hco": "米蘭時尚診所 桃園館", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-07-28", "lastFeedback": "本次電聯預約明日拜訪陳彥霖醫師，先與白藥師交流了解達促朗目前使用狀況，白藥師表示，醫師目前達促朗使用狀況穩定，且桃園地區的處方是釋出的，暫時不需特別安排拜訪，而陳醫師主要以病人需求為主，若痔瘡症狀較嚴重，會考慮於術前先使用；若病人手術排程時間較長，也會搭配使用，以協助改善症狀。藥師表示，達促朗主要仍依病人嚴重程度評估使用時機，若有安排手術之病人，通常也會搭配。", "savedNext": "", "notes": ""}, {"id": "001Tn00000bgszbIAA", "hcp": "明倫 劉", "hco": "楊延壽診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市龍潭區", "lastVisit": "2026-07-22", "lastFeedback": "拜訪劉醫師探討其處方狀況。劉醫師表示，對於焦慮憂鬱且伴隨睡眠障礙的病人，會優先考慮使用相關藥物，以減少病人同時服用多種藥物的情形。對於無法耐受SSRI副作用的病人，劉醫師認為影響不大，因其處方習慣為以較低初始劑量開始，讓病人逐步適應。\n同時與劉醫師分享煩多閃在維持體重中線方面的相關文獻，劉醫師表示百憂解亦有類似效果，並提到部分減肥門診會不當使用藥物，甚至開立百憂解給病人。進一步分享文獻中關於體重變化的數據，並建議未來若遇到代謝症候群、肥胖或對體重較為在意的病人，可考慮相關用藥選擇。劉醫師表示未來在處方上會持續觀察與評估。", "savedNext": "", "notes": ""}, {"id": "001Tn00000bo9ilIAA", "hcp": "益宗 詹", "hco": "好膽胰診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-07-24", "lastFeedback": "本次拜訪請詹益宗醫師協助完成 8/29–8/30 SPA-MIND 活動之贊助合約書。另詢問詹醫師，臨床上是否曾遇過病人服用達促朗後出現噁心、嘔吐情形。詹醫師表示，目前完全未曾遇過類似個案，並進一步詢問是否已有其他病人發生相關症狀。告知詹醫師，近期曾有一位病人出現明顯噁心、嘔吐反應。詹醫師認為，達促朗整體耐受性良好，若病人症狀較嚴重，建議仍應進一步安排其他檢查，以排除藥物以外的可能原因。醫師亦表示，其臨床使用經驗中，尚未遇過病人因服用達促朗而出現明顯不適。", "savedNext": "", "notes": ""}, {"id": "001Tn00000bocG5IAI", "hcp": "建霖 何", "hco": "青心診所", "specialty": "Colorectal Surgery", "product": "Daflon", "adoption": "High Prescriber", "grade": "A", "target": 6, "area": "新竹縣竹北市", "lastVisit": "2026-08-07", "lastFeedback": "拜訪何醫師，請醫師協助完成 8/29–30 SPA 醫學研討會之贊助合約書，交流過程中，關心何醫師近期台中新開診所的營運情形。何醫師表示，目前仍處於試營運階段，病人數量尚未穩定；竹北診所其實也才開業約一年，今日看診人數約 10 位，且目前患者以 GI 相關問題為主，何醫師表示，近期正逐步透過媒體及相關管道經營自己，希望先累積曝光度及知名度，待流量提升後，預期病人數也會逐漸增加。", "savedNext": "", "notes": ""}, {"id": "001Tn00000BxAKZIA3", "hcp": "雨欣 劉", "hco": "立群診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Undecided / Unaware", "grade": "C", "target": 2, "area": "桃園市平鎮區", "lastVisit": "2026-05-21", "lastFeedback": "櫃檯護理師表示拜訪劉醫師需先跟行政預約，故待下次預約後再拜訪。", "savedNext": "", "notes": ""}, {"id": "001Tn00000cc4xbIAA", "hcp": "怡均 林", "hco": "均安身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-07-24", "lastFeedback": "本次拜訪詢問李青樺醫師，煩多閃主要會使用於哪些類型的病人。李醫師表示，個人相當喜歡使用煩多閃，初診病人或曾因其他抗憂鬱劑產生副作用的病人，皆會視情況評估使用；惟 18 歲以下病人不會使用。李醫師表示，目前臨床上尚未遇過病人因煩多閃出現明顯副作用。近期因遇到多位接受植牙治療，以及使用 SSRI 後治療效果不理想的病人，因此更常考慮使用煩多閃。李醫師提到，其先生為牙醫師，曾向她分享 SSRI 或 SNRI 類藥物可能影響植牙治療結果的相關文獻。因此，其先生遇到正在使用此類藥物且有相關疑慮的病人時，會轉介至李醫師處進一步評估。由於部分精神科醫師對此觀點持不同看法，李醫師表示，另有精神科醫師曾整理相關文獻，未來若規劃相關演講或需要進一步資料，可再聯繫該醫師討論。另與李醫師分享煩多閃在體重影響方面相對中性的相關文獻。李醫師表示已閱讀過該資料並了解其內容，因此對於有體重控制需求、代謝症候群或三高風險的病人，也會優先考慮使用煩多閃。\n後續可持續追蹤李醫師於 SSRI／SNRI 不耐受、植牙治療及代謝風險病人中的處方經驗，並提供相關文獻與學術活動資訊。", "savedNext": "", "notes": ""}, {"id": "001Tn00000cYGclIAG", "hcp": "秉竑 何", "hco": "上杉診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 2, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "拜訪楊士豪醫師，了解診間痔瘡病人及達促朗目前的處方情形。楊醫師表示，近期診間痔瘡病人蠻多的，亦有執行冷凍及結紮等相關處置。目前達促朗主要會處方於具有明顯症狀的痔瘡病人；若為第四期痔瘡，通常會直接轉介至醫學中心進一步處理。至於接受冷凍或結紮手術的病人，因醫師觀察術後恢復狀況普遍良好，目前較少搭配達促朗使用。針對術後治療情境，向楊醫師分享達促朗亦有相關文獻探討於門診術後使用，可協助減緩術後腫脹及疼痛。楊醫師表示了解，告知醫師下次拜訪時將攜帶相關文獻供其參考，後續再進一步討論達促朗於術後照護的應用。", "savedNext": "", "notes": ""}, {"id": "001Tn00000d3eFQIAY", "hcp": "暉復 黃", "hco": "昇暉診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-06-24", "lastFeedback": "拜訪黃醫師，了解 5/28 叫貨達促朗後之處方狀況。黃醫師表示，目前已有開立給痔瘡病人使用，病人使用後效果皆還不錯，目前處方方式為每日 2 顆。不過因診間病人數較少，目前尚無較多案例可進一步分享，並詢問黃醫師是否需要達促朗用藥小卡，黃醫師表示好，待下次拜訪拿至診間。\n另再向黃醫師說明，達促朗亦可應用於下肢慢性靜脈疾病病人，並分享相關症狀如腿部沉重感、痠脹、腫脹及夜間抽筋等。黃醫師表示，至診間就診且有慢性靜脈疾病症狀的病人，多為年長族群，通常會覺得自費藥物價格較高。再次與黃醫師溝通，若病人症狀已造成明顯困擾，仍可能具備使用意願，建議可於合適病人身上嘗試處方。黃醫師表示，後續若遇到有相關症狀之病人，會考慮開立達促朗，後續將持續追蹤使用狀況", "savedNext": "", "notes": ""}, {"id": "001Tn00000d99nDIAQ", "hcp": "人碩 郭", "hco": "崇光身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-08-14", "lastFeedback": "拜訪郭人碩醫師，邀請醫師參加 8/29–30 DDM 醫學研討會活動。郭醫師表示，該週已與高中同學安排聚會，行程已有安排，因此此次無法參加 DDM 活動。後續將於未來有合適的學術活動時再進行邀約。", "savedNext": "", "notes": ""}, {"id": "001Tn00000DbdZHIAZ", "hcp": "瑋萱 歐", "hco": "九禾藥局(陳炯旭診所)", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "因陳醫師於本週日生日，今日特別至診間向陳醫師提前送上生日祝福，並與醫師交流近況、維持PR。", "savedNext": "", "notes": ""}, {"id": "001Tn00000doZ7RIAU", "hcp": "俊明 李", "hco": "李俊明診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "C", "target": 2, "area": "桃園市平鎮區", "lastVisit": "2026-07-22", "lastFeedback": "本次先至藥局拜訪藥師，了解煩多閃近期的使用及庫存情形。藥師表示，診所目前仍有持續使用煩多閃，近期也已自行透過訂購網站追加三盒，但整體處方仍以 SSRI 類藥物為主。向藥師說明，若診所後續皆以三盒為單位持續補貨，可評估改採 10+1 的訂購方案，整體價格會較為划算。藥師表示，每次訂購數量主要仍由李醫師依照網站顯示的總金額決定，本次李醫師僅指示訂購三盒，並已了解 10+1 的方案資訊。後續由櫃檯人員協助詢問李醫師，醫師起初表示可以接受拜訪。惟等候約二十分鐘期間陸續有病人報到，櫃檯人員說明李醫師看診期間通常不會中途接待業務，若繼續等候，可能需待所有病人看診結束後才有機會拜訪。櫃檯建議改於週四或週五前往，當日病人數通常較少，較適合安排拜訪。故本次先行離開，後續將改於週四或週五再次前往，進一步了解李醫師的處方考量及煩多閃使用情形。", "savedNext": "", "notes": ""}, {"id": "001Tn00000dy7o9IAA", "hcp": "宇鴻 羅", "hco": "福祐診所", "specialty": "Emergency (ER)", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 2, "area": "桃園市桃園區", "lastVisit": "2026-08-12", "lastFeedback": "因上次拜訪時羅醫師曾詢問移工輪班族群使用煩多閃的相關用藥方式，本次帶相關文獻與醫師分享，針對輪班族群的睡眠及用藥情境進一步交流。過程中羅醫師主動詢問達促朗相關資訊，提及先前曾遇到一位下肢靜脈曲張病人，詢問達促朗是否能改善相關問題。進一步了解病人目前僅有外觀上的靜脈曲張，並無明顯疼痛、腫脹或其他症狀。向羅醫師說明，達促朗主要著重於改善慢性靜脈疾病相關症狀，若主要訴求為靜脈曲張之外觀問題，仍需視情況由外科進一步評估及處理。羅醫師表示了解，後續將再觀察診間相關病人情形。告知醫師下次拜訪時將攜帶相關臨床案例與醫師分享，持續交流達促朗於慢性靜脈疾病病人的適用情境。", "savedNext": "", "notes": ""}, {"id": "0011i00000cJ6fdAAC", "hcp": "志瑋 陳", "hco": "尚語身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-05", "lastFeedback": "拜訪楊凱仲醫師，了解達促朗近期臨床使用情形。楊醫師表示，若痔瘡病人使用健保藥物治療效果不佳，通常會直接建議自費使用達促朗，並向病人說明達促朗除可用於痔瘡外，亦可改善慢性靜脈疾病及下肢靜脈曲張相關症狀。醫師提到，診所另外兩位醫師較擔心病人對自費藥物的接受度，因此多半會先建議使用艾歐復隆，但依其臨床經驗，治療效果相對有限。若遇到腫脹嚴重或需積極處置的痔瘡病人，則會直接轉介外科評估手術治療。進一步向楊醫師分享達促朗搭配痔瘡手術使用，可協助減輕術後疼痛及水腫的相關文獻。楊醫師表示，先前曾參加外科相關課程，了解達促朗於痔瘡治療具有良好的臨床療效，因此對產品相當熟悉。最後邀請楊醫師參加 8/29–30 SPA 醫學研討會活動，醫師表示時間上應可配合，待後續 Agenda 確認後，將再提供活動資訊並完成邀約。", "savedNext": "", "notes": ""}, {"id": "0017U00000Kx4zpQAB", "hcp": "宛庭 蔡", "hco": "正文身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-08-03", "lastFeedback": "拜訪蔡醫師，了解煩多閃近期處方狀況。蔡醫師表示，病人整體使用回饋良好，尤其在改善睡眠及焦慮症狀方面表現不錯；至於憂鬱症狀的改善則相對較為溫和。不過醫師也認為，煩多閃的療效仍具有個體差異，有些病人反應非常良好，也有部分病人覺得效果較不明顯。蔡醫師表示，目前臨床上大多以一顆處方為主，主要考量高劑量使用時仍需留意肝功能監測。若病人使用一顆，通常不會特別安排抽血追蹤；若需增加至兩顆，則會依仿單建議安排肝功能檢測。醫師表示，目前僅遇過約 1–2 位病人出現肝功能指數輕微升高，約一百多 U/L，停藥後皆恢復正常。另蔡醫師分享一位 ADHD 合併焦慮症病人的臨床經驗。該病人使用利他能合併煩多閃治療，整體控制情形良好；即使後續僅使用煩多閃，病人仍表示療效不錯。至於恐慌症病人，蔡醫師仍較傾向優先使用 SSRI，認為臨床效果相對較佳，但也強調不同醫師的處方習慣仍有所差異。最後與蔡醫師分享煩多閃維持體重中性的相關文獻。蔡醫師表示，雖然臨床上因體重問題而更換抗憂鬱藥物的病人並不多，但確實有部分病人會在意體重變化。考量目前全球對體重管理及代謝健康的重視，此特色是一個不錯的臨床切入點，未來若遇到在意體重、肥胖或合併代謝症候群的病人，將會優先考慮使用煩多閃作為治療選項。", "savedNext": "", "notes": ""}, {"id": "00158000019UBygAAG", "hcp": "錚宜 楊", "hco": "安立身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹縣竹北市", "lastVisit": "2026-07-16", "lastFeedback": "拜訪楊醫師，了解煩多閃目前的處方情形。楊醫師表示，安立身心診所當初會進用煩多閃，是由其主動提出需求。醫師目前主要門診仍在東元醫院，過往於醫院端即經常使用煩多閃，認為此藥物臨床上相當實用。雖然整體療效相對溫和，但副作用少，且與其他藥物併用時較少出現交互作用問題。針對肝功能監測，楊醫師表示並不認為此為煩多閃的主要副作用。醫師在向病人說明時，通常會解釋煩多閃屬於較新的藥物，且主要經肝臟代謝，因此基於較嚴謹的用藥原則，仍會建議病人定期檢測肝功能。實際臨床上肝功能指數升高的比例不高，醫師目前僅遇過一位病人，且指數僅輕微上升。楊醫師表示，煩多閃的療效仍因人而異，不同病人的治療反應有所差異。但對於初診的憂鬱或焦慮病人，若同時伴隨睡眠障礙，通常會優先考慮使用煩多閃，認為此類病人相當適合。拜訪過程中與楊醫師分享煩多閃維持體重中性的相關文獻，醫師對此資料感到相當新鮮，並主動要求提供完整文獻供其參考。楊醫師總結認為，煩多閃具備副作用少、較不影響性功能、較少造成腸胃道不適、可協助改善睡眠等優點，若再加上維持體重中性的特性，將是臨床上一項不錯的治療選擇。", "savedNext": "", "notes": ""}, {"id": "001Tn00000iOhC9IAK", "hcp": "其翔 陳", "hco": "馬大元診所/全民好藥局", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "新竹市東區", "lastVisit": "2026-08-10", "lastFeedback": "拜訪陳其祥醫師，先進行自我介紹並了解診間主要病人族群。陳醫師雖具老人精神科專業，但表示目前診間老年病人比例並不高，主要還是以失眠相關患者為主。進一步詢問醫師對於失眠病人的用藥習慣，陳醫師表示仍會依病人整體症狀及臨床需求決定單一藥物或合併其他藥物治療。若遇到憂鬱合併失眠的病人，臨床上也會使用煩多閃治療。陳醫師表示，部分病人會自行查詢煩多閃相關資訊後，因看到可能影響肝功能而產生疑慮，不過實際安排病人檢查後，目前並未遇到肝功能指數升高的情形。針對醫師及病人對肝功能監測的疑慮，告知下次拜訪時將攜帶相關肝功能安全性文獻與醫師分享，進一步交流煩多閃的臨床使用經驗。", "savedNext": "", "notes": ""}, {"id": "001Tn000002nN3xIAE", "hcp": "伯翰 周", "hco": "周伯翰身心醫學診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-05-19", "lastFeedback": "因門診時間有變動，故未拜訪到周醫師，已請櫃檯護理師協助確認5/26活動之相關事宜。", "savedNext": "", "notes": ""}, {"id": "001Tn00000caILVIA2", "hcp": "文沿 曹", "hco": "周伯翰身心醫學診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-08-25", "lastFeedback": "拜訪鄭醫師，了解目前煩多閃之處方情形。鄭醫師表示，目前處方煩多閃時主要使用 F41.1 診斷碼。向醫師補充說明，煩多閃另有 F32.9 相關適應症診斷碼；鄭醫師表示了解，並提到 F32.9 為未明示的憂鬱症，因此目前仍習慣以 F4.1 為主要處方診斷。交流過程中，鄭醫師詢問未來仿單是否有機會擴增兒童族群適應症。醫師表示，兒童可使用的抗憂鬱藥物選擇相對有限，而依其臨床感受，認為煩多閃可能適合部分兒童患者，但因目前仿單未涵蓋兒童使用，因此臨床上也不敢開立，擔心產生相關醫療風險。針對此部分，向鄭醫師說明目前尚未得知仿單近期有擴增兒童適應症的規劃；另外從現有研究來看，兒童族群的研究樣本數仍不足，若未來要進一步支持兒童適應症，可能仍需要更多大型臨床研究資料。另外，鄭醫師提到曾聽周醫師分享，煩多閃的適應症主要為焦慮症及憂鬱症，因此不能單純因病人有失眠症狀就開立煩多閃。對此向醫師確認，煩多閃應使用於符合核准適應症的焦慮症或憂鬱症患者，若同時伴隨睡眠問題，則可將睡眠症狀改善作為治療上的額外考量，而非單純以失眠作為開立依據。進一步詢問鄭醫師對煩多閃改善睡眠的臨床回饋，醫師表示整體效果尚可，對部分病人確實有幫助；加上臨床上感受到副作用相對少，因此目前使用上相對順手，整體而言是一個不錯的藥物選擇。\n", "savedNext": "", "notes": ""}, {"id": "001Tn00000caIQLIA2", "hcp": "柏安 陳", "hco": "周伯翰身心醫學診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-07-08", "lastFeedback": "拜訪陳醫師，了解煩多閃目前處方狀況。陳醫師提及，院內周院長規定若要使用煩多閃，診斷碼僅能下 F41.1，因此詢問產品適應症是否只能用於廣泛性焦慮症。已向陳醫師說明，煩多閃目前適應症包含憂鬱症與廣泛性焦慮症，因此 F41.1 與 F32.9 皆可作為相關診斷碼使用。陳醫師表示不清楚為何周醫師要求僅能下 F41.1，且周醫師會定期查閱病歷紀錄。後續若有機會，建議可再拜訪周醫師，進一步了解其對煩多閃處方規範與診斷碼使用的考量。\n進一步詢問陳醫師目前煩多閃主要使用於何種病人。陳醫師表示，若病人有憂鬱或焦慮並伴隨失眠時會考慮使用，但整體而言，他認為煩多閃在憂鬱症病人身上的療效較佳；若為焦慮症病人，則較常使用 Paroxetine。\n接著詢問醫師在憂鬱症病人中，是否會特別用於心情低落、對事情失去興趣或缺乏動力等症狀。陳醫師表示這類症狀皆會考慮使用，但也提到若病人主要表現為失去動力、對事情沒興趣，臨床上可能仍會傾向選擇與 dopamine 相關的藥物。後續向醫師說明煩多閃具 MT1/MT2 受體作用及 5-HT2C 受體拮抗作用，因此可增加前額葉 norepinephrine 與 dopamine，並詢問醫師是否曾觀察到其在缺乏動力病人身上的效果。陳醫師表示過去未特別注意此點，但後續會再觀察煩多閃於此類病人身上的療效表現。", "savedNext": "", "notes": ""}, {"id": "0017U00000PxizIQAR", "hcp": "子懿 徐", "hco": "舒欣身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "新竹市東區", "lastVisit": "2026-05-19", "lastFeedback": "向藥師告知未來由我負責服務此區域，並詢問是否可拜訪徐醫師，藥師表示徐醫師現在病人還很多且僅在此診所服務至這個月底。", "savedNext": "", "notes": ""}, {"id": "001Tn00000XzO2UIAV", "hcp": "斐雯 楊", "hco": "振心身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-07-07", "lastFeedback": "拜訪楊醫師，詢問目前煩多閃主要處方族群是否為憂鬱、焦慮合併睡眠問題，或對 SSRI／SNRI 耐受性不佳的病人。楊醫師表示，基本上若病人主述有憂鬱、焦慮且合併睡眠問題時，皆會考慮使用煩多閃。進一步詢問醫師在什麼情境下會優先想到煩多閃，醫師表示主要仍會針對睡眠問題，以及對 SSRI／SNRI 耐受性不佳的病人。\n接著詢問楊醫師對於煩多閃使用在失去興趣、缺乏愉悅感或動力不足病人身上的效果觀察。楊醫師表示，目前臨床觀察下來，此類症狀的改善效果並未特別顯著。後續向醫師說明，煩多閃除作用於 melatonin receptor 外，亦具 5-HT2C antagonism，可增加前額葉 dopamine 及 norepinephrine，因此想進一步了解醫師在缺乏動力、失去興趣或快樂感降低病人身上的實際使用經驗。楊醫師表示了解，後續會再多觀察此類病人的反應。\n進一步詢問若遇到焦慮病人，告知需注意肝功能監測時，是否會影響醫師開立意願。楊醫師表示，煩多閃主要會使用於有特定煩惱來源的焦慮病人；若為廣泛性焦慮病人，無論說明任何副作用，病人都可能較容易焦慮。因此醫師仍會完整向病人解釋藥物特性與注意事項，並讓病人共同選擇適合的治療方式。\n後續與楊醫師分享煩多閃在體重維持相關文獻。楊醫師表示，目前在使用抗憂鬱藥物的病人中，並未特別觀察到明顯體重增加問題；但若未來遇到三高或代謝症候群風險較高的病人，或許會考慮嘗試使用煩多閃。\n最後邀請楊醫師參加 7/22 餐敘活動。楊醫師查看行事曆後表示，因先生當天值班，需照顧小孩，故無法參加。拜訪結束前，再次與醫師討論後續可觀察煩多閃用於缺乏動力、失去興趣病人身上的實際效果，楊醫師表示沒問題。", "savedNext": "", "notes": ""}, {"id": "001Tn000000gi33IAA", "hcp": "揚毅 馮", "hco": "蘆竹現代診所", "specialty": "Internal Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "B", "target": 3, "area": "桃園市蘆竹區", "lastVisit": "2026-06-22", "lastFeedback": "拜訪馮醫師並詢問達促朗近期使用狀況。馮醫師表示，由於達促朗屬自費藥物，目前在治療順序上會較偏後線，主要是擔心病人一開始即使用自費藥物，可能會產生「診所是否刻意推銷高價藥物」的疑慮。因此，除非病人看起來經濟能力較佳，且希望能快速緩解不適症狀，醫師才會較主動介紹達促朗。目前針對初期痔瘡病人，馮醫師多會先以寧治腫搭配艾歐復龍給予治療；若病人症狀仍未改善，才會進一步告知病人有另一項效果不錯、但費用較高的藥物選擇，並依病人意願決定是否使用達促朗。醫師表示，臨床上病人使用達促朗後，症狀多有明顯改善。另詢問馮醫師診間是否有執行痔瘡相關手術，醫師表示目前診所並未進行痔瘡手術，蘆洲現代診所的陳品箏醫師則有執行痔瘡冷凝刀治療。最後邀請馮醫師參加 7/11–7/12 SPA 活動，馮醫師表示該週已安排返台中，故無法參加此次活動。", "savedNext": "", "notes": ""}, {"id": "001Tn00000hm4v4IAA", "hcp": "士豪 楊", "hco": "上杉診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "拜訪楊士豪醫師，了解診間痔瘡病人及達促朗目前的處方情形。楊醫師表示，近期診間痔瘡病人蠻多的，亦有執行冷凍及結紮等相關處置。目前達促朗主要會處方於具有明顯症狀的痔瘡病人；若為第四期痔瘡，通常會直接轉介至醫學中心進一步處理。至於接受冷凍或結紮手術的病人，因醫師觀察術後恢復狀況普遍良好，目前較少搭配達促朗使用。針對術後治療情境，向楊醫師分享達促朗亦有相關文獻探討於門診術後使用，可協助減緩術後腫脹及疼痛。楊醫師表示了解，告知醫師下次拜訪時將攜帶相關文獻供其參考，後續再進一步討論達促朗於術後照護的應用。", "savedNext": "", "notes": ""}, {"id": "001Tn00000feeNKIAY", "hcp": "馗晉 黃", "hco": "敏昌診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "桃園市中壢區", "lastVisit": "2026-08-13", "lastFeedback": "拜訪黃醫師，與醫師交流達促朗及煩多閃之臨床使用情形。首先詢問達促朗相關使用狀況，黃醫師表示對達促朗已有一定了解，並認為慢性靜脈疾病的內科治療約能改善部分病人的症狀，臨床上仍需搭配彈性襪及生活習慣調整，以達到較完整的治療效果。接著探討煩多閃處方情形，黃醫師表示，對於煩多閃在台灣的使用量相當有印象，也認為公司的行銷策略相當成功。醫師提到，過去對煩多閃的認知主要為憂鬱症治療，對於目前也有醫師將其應用於焦慮症患者感到好奇。黃醫師分享其臨床經驗，認為煩多閃單獨用於重鬱症患者時療效較不明顯，但若與 SSRI 合併使用，臨床效果則較佳；惟若涉及健保給付規範，診所端在處方上仍會有所限制。進一步了解診間主要病人族群，黃醫師表示以中老年患者居多，年輕族群相對較少。針對中年患者可能出現因過度思慮、焦慮合併睡眠問題的情況，與醫師分享其他臨床醫師使用煩多閃於此類病人的回饋，黃醫師表示了解。另外，黃醫師表示自己對煩多閃改善睡眠的效果評價尚可，但臨床上仍會視病人情況搭配其他藥物。向醫師說明煩多閃作用於褪黑激素受體，若能搭配規律作息，有助於調整睡眠。黃醫師表示對此已有了解，目前診間煩多閃處方量其實也不少。最後建議醫師未來若遇到合併睡眠問題及焦慮症狀的中年患者，可再嘗試評估煩多閃的使用，黃醫師表示認同，後續會再增加相關處方嘗試。", "savedNext": "", "notes": ""}, {"id": "001Tn00000eu8bmIAA", "hcp": "順征 江", "hco": "長安診所_桃園蘆竹", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "桃園市蘆竹區", "lastVisit": "2026-08-05", "lastFeedback": "拜訪江順征醫師，了解達促朗近期臨床使用情形。江醫師表示，目前自己持續早晚服用達促朗，明顯感受到下肢腫脹感有所改善，因此對產品具有相當信心。醫師表示，若遇到慢性靜脈疾病合併靜脈性潰瘍的病人，也會建議使用達促朗，病人回診時整體症狀大多都有改善，臨床回饋相當不錯。交流過程中，江醫師分享自己對黃酮類成分相當有興趣，也曾利用 AI 查詢大量相關研究，特別關注橙皮素的抗老化潛力，甚至進一步查詢臺灣柑橘品種中橙皮素含量較高的相關資訊。醫師也提到，了解到此類黃酮成分空腹服用時吸收較差。向醫師說明，因此建議達促朗於餐中或飯後服用，以提升吸收效果，同時分享達促朗採用微粒化純化黃酮劑（MPFF）技術，可進一步提高生體可用率。江醫師表示，相關內容皆已有深入研究並充分了解，目前仍持續規律服用達促朗，也會持續觀察病人使用後的臨床反應及療效。", "savedNext": "", "notes": ""}, {"id": "0011i00000llqXRAAY", "hcp": "采燁 謝", "hco": "親禾身心診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "新竹市東區", "lastVisit": "2026-08-06", "lastFeedback": "拜訪謝采燁醫師，與醫師建立初步關係，並邀請醫師參加 8/29–30 醫學研討會活動。謝醫師表示，需再確認當日行程安排後才能決定是否參加。交流過程中與醫師交換聯絡方式，並告知後續將傳送活動 Agenda 及相關資訊，供醫師參考。後續將持續追蹤醫師參與意願。", "savedNext": "", "notes": ""}, {"id": "001Tn00000hRkxHIAS", "hcp": "元郁 林", "hco": "龍和內兒科診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "桃園市桃園區", "lastVisit": "2026-07-27", "lastFeedback": "本次拜訪林醫師，了解近期達促朗處方狀況。林醫師表示，目前主要將達促朗使用於痔瘡反覆發作的病人，通常一次開立一盒供病人使用。病人用藥後多未再因相同症狀回診，醫師推測症狀應已有改善。另詢問診間是否有排除心、肝、腎等問題後，仍出現下肢水腫、腫脹或夜間抽筋的病人，並向林醫師分享達促朗應用於慢性靜脈疾病及下肢靜脈症狀的相關文獻。林醫師表示了解，目前診間此類病人較少，但未來若遇到合適個案，會考慮嘗試使用達促朗。醫師進一步詢問是否有機會於診所內舉辦 Seminar，並協助提供相關接洽窗口。後續將與窗口聯繫，確認活動時間、主題及執行細節。", "savedNext": "", "notes": ""}, {"id": "001Tn00000feRQLIA2", "hcp": "鏘華 廖", "hco": "崇光小兒專科診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Low Prescriber", "grade": "A", "target": 6, "area": "新竹縣竹東鎮", "lastVisit": "2026-07-02", "lastFeedback": "拜訪廖醫師，詢問達促朗目前的使用狀況。廖醫師表示目前銷售狀況不錯，主要使用於慢性靜脈疾病病人。\n醫師進一步詢問是否有再更大量的搭贈選擇。後續向廖醫師說明 15+3 的訂購方案，廖醫師表示可於今日訂購。接著詢問廖醫師，公司有製作慢性靜脈疾病相關衛教海報，是否有意願張貼於診所公告欄。廖醫師表示沒有問題，故規劃於下次拜訪時攜帶海報至診所，提供醫師張貼使用。", "savedNext": "", "notes": ""}, {"id": "001Tn00000AKbLpIAL", "hcp": "景雄 曹", "hco": "曹景雄小兒科診所", "specialty": "Family Medicine", "product": "Daflon", "adoption": "Trialist", "grade": "B", "target": 3, "area": "桃園市桃園區", "lastVisit": "2026-08-31", "lastFeedback": "因上次未能順利拜訪曹景雄醫師，本次先以訊息詢問醫師近期是否方便安排拜訪，並同步關心達促朗近期處方使用情形，惟尚未收到醫師回覆。故本次直接前往診所預計拜訪，但現場依然病人眾多，考量醫師看診繁忙，本次未再等候拜訪<後續預計隔日再以電話聯繫曹醫師，確認方便的拜訪時段，並進一步追蹤近期達促朗處方情形及是否有需要協助之處。", "savedNext": "", "notes": ""}, {"id": "001Tn00000fP0lBIAS", "hcp": "文彬 蕭", "hco": "姜博文診所", "specialty": "Cardiology", "product": "Daflon", "adoption": "Undecided / Unaware", "grade": "B", "target": 3, "area": "桃園市楊梅區", "lastVisit": "2026-06-30", "lastFeedback": "拜訪蕭醫師，蕭醫師為心臟內科醫師，目前至診所服務約半年。首先詢問醫師是否曾使用過達促朗，醫師表示未曾使用過，也未曾聽過此藥物，過去於醫院服務時並未接觸過達促朗。\n接著詢問醫師臨床上是否常遇到下肢水腫、夜間抽筋、下肢腫脹疼痛等病人，尤其是經檢查心、肝、腎功能無明顯異常者。醫師表示通常若病人有水腫，多半仍會有相關原因，也可能與藥物引起的水腫有關。進一步詢問醫師是否會考慮慢性靜脈疾病的可能性，醫師未特別回覆。後續向醫師介紹達促朗可用於慢性靜脈疾病，並說明其針對下肢腫脹、疼痛、沉重感及夜間抽筋等症狀的療效，同時分享相關文獻與作用機轉。醫師進一步詢問達促朗為何能增加靜脈張力，故向醫師說明達促朗可透過抑制 COMT，增加靜脈血管壁對 noradrenaline 的反應，進而提升靜脈張力、減少靜脈擴張與血液滯留。\n醫師接著詢問是否會造成血壓上升。向醫師說明達促朗主要作用於靜脈血管壁，改善靜脈回流與微循環，並非像升壓藥直接作用於動脈血管造成周邊阻力上升，因此臨床上不會以血壓上升作為主要疑慮。\n蕭醫師表示目前完全沒有接觸過此藥物，因此仍希望再進一步釐清其作用機轉，也會自行查找資料了解。隨後告知醫師，若後續對機轉或臨床文獻有任何問題，皆可再提供資料與醫師分享；也會於下次拜訪時帶其他診間醫師使用達促朗於慢性靜脈疾病病人的實際療效案例，作為臨床應用參考。醫師表示沒有問題。", "savedNext": "", "notes": ""}, {"id": "001Tn00000gPBBQIA4", "hcp": "靖 張", "hco": "日日安內科診所", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Undecided / Unaware", "grade": "B", "target": 3, "area": "桃園市大園區", "lastVisit": "2026-08-24", "lastFeedback": "拜訪張醫師，了解診間痔瘡病人及目前治療情形，張醫師表示，診間痔瘡患者比例不少，近期原本有考慮開始提供冷凝刀治療，但詢問過去同事後，得知臨床療效可能不如預期，因此目前仍在評估。進一步向張醫師介紹達促朗相關資訊及臨床應用，張醫師表示，目前診所預計進行擴大，現階段藥物主要釋出至隔壁藥局；待診所擴大後，若評估進藥，未來可能考慮將達促朗放置於診所端自行販售及提供病人使用。張醫師表示後續會再評估相關需求，若確定有進藥規劃會再與我聯繫。", "savedNext": "", "notes": ""}, {"id": "001Tn00000eKf9eIAC", "hcp": "康維 彭", "hco": "竹北現代內科", "specialty": "Gastroenterology", "product": "Daflon", "adoption": "Trialist", "grade": "B", "target": 3, "area": "新竹縣竹北市", "lastVisit": "2026-08-19", "lastFeedback": "本次先拜訪護理長，討論診所 Seminar 辦理時間。護理長表示，預計於 9 月例會中決定 10 月例會日期，確認後會再告知適合辦理 Seminar 的時間，後續將持續追蹤。接著拜訪彭醫師，了解達促朗近期處方及病人回饋。彭醫師表示，目前已有處方達促朗於病人身上，但其中 3 位痔瘡病人使用後便未再回診，因此無法確認後續療效。其中一位為產後媽媽，醫師曾提醒病人暫停哺乳後再使用。另外一位為年長女性，主要症狀為下肢水腫及夜間抽痛。因病人原本預計回診看檢查報告，因此先處方一週觀察，但病人回饋療效不明顯。針對此案例，向彭醫師說明慢性靜脈疾病患者通常建議持續使用一段時間，以觀察較完整的治療反應；若患者症狀較明顯，也可依臨床情況評估適當的劑量。彭醫師表示了解，後續遇到類似病人會再嘗試處方並觀察病人回饋。後續將持續追蹤 Seminar 時程及達促朗病人使用情形。", "savedNext": "", "notes": ""}, {"id": "001Tn00000dpXl3IAE", "hcp": "昌履 林", "hco": "晨新診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Medium Prescriber", "grade": "A", "target": 6, "area": "桃園市蘆竹區", "lastVisit": "2026-08-21", "lastFeedback": "因林昌履醫師居住於台北，邀請醫師參加 8/29–30 DDM醫學研討會活動。林醫師表示，假日通常需陪伴小孩，因此此次無法參加；惟對於活動中「更年期婦女」及「移工晝夜節律」相關議題相當有興趣。交流過程中，林醫師分享近期臨床案例，診間有不少移工患者；另外近期遇到一位更年期患者，主要症狀包含睡眠問題、夜間盜汗及憂鬱，先前使用 SSRI 後效果不佳，近期改用煩多閃，目前病人回饋症狀已有改善。此外，林醫師分享前陣子曾遇到一位神經痛患者，由神經內科醫師處方煩多閃 BID 使用，並詢問是否有其他神經內科醫師採取類似的處方方式。針對此部分，告知醫師將再與公司 PM 確認相關臨床經驗及資訊後回覆。林醫師另外詢問煩多閃與其他藥物合併使用是否有相關文獻。告知醫師，待 DDM 研討會結束後，將詢問講者是否能提供相關 Slide，若可取得再與醫師分享；另合併用藥相關文獻將整理後於下次拜訪時提供。後續將持續追蹤神經痛相關處方資訊，並準備煩多閃合併用藥之相關文獻與醫師進一步交流。", "savedNext": "", "notes": ""}, {"id": "00158000019UCCLAA4", "hcp": "仁豪 李", "hco": "晨新診所", "specialty": "Psychiatry", "product": "Valdoxan", "adoption": "Trialist", "grade": "B", "target": 3, "area": "桃園市蘆竹區", "lastVisit": "2026-07-15", "lastFeedback": "拜訪李醫師，了解其對煩多閃的認識及臨床使用情形。李醫師表示，目前尚未使用煩多閃，但曾聽林昌履醫師分享，認為煩多閃是一顆副作用較少的抗憂鬱藥物，因此對產品具有興趣。因醫師對煩多閃尚未十分熟悉，故向醫師介紹其作用機轉、臨床定位及適應症等相關資訊。李醫師表示，了解後認為煩多閃是一個不錯的治療選擇，也提到此類較新的藥物，許多資深醫師未必熟悉，同時也擔心臨床使用時是否會有健保核刪的問題。因此進一步向醫師說明煩多閃的仿單適應症及臨床使用情境，並分享目前醫師端的使用經驗，以增加醫師對產品的了解與信心。拜訪過程中，李醫師亦分享自身執業經歷，表示約半年前自桃園療養院離職後至診所執業。因醫師對煩多閃持開放態度，後續將持續分享其他醫師的臨床處方經驗及最新文獻，作為未來臨床使用之參考。", "savedNext": "", "notes": ""}];
